const releaseBody = "WEBVTT\nX-TIMESTAMP-MAP=MPEGTS:900000,LOCAL:00:00:00.000\n\nSTYLE\n::cue(.styledotitalic) { font-style:italic }\n::cue(.styledotdefault) { background-color:transparent }\n\n9901803\n00:00:47.640 --> 00:00:49.720 align:middle line:85%,start position:50%,middle\nGitHub：rexchen1803\n\n1\n00:00:49.800 --> 00:00:51.193 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“致亲爱的克里斯</c>\n\n2\n00:00:53.679 --> 00:00:56.740 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我一直在想如何能告诉你\n你对我有多么重要</c>\n\n3\n00:01:00.811 --> 00:01:04.331 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我仍记得刚爱上你时的情景\n恍如昨夜</c>\n\n4\n00:01:06.358 --> 00:01:09.169 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在那间小公寓里与你赤裸相依</c>\n\n5\n00:01:10.904 --> 00:01:14.091 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我突然意识到\n自己也是这宏大整体的一部分</c>\n\n6\n00:01:15.242 --> 00:01:16.677 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就像我们的父母</c>\n\n7\n00:01:17.452 --> 00:01:18.887 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或是我们父母的父母</c>\n\n8\n00:01:21.623 --> 00:01:25.352 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在那之前 我只是混沌度日\n以为自己什么都懂</c>\n\n9\n00:01:26.228 --> 00:01:31.275 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>突然这道光芒射向我 唤醒了我</c>\n\n10\n00:01:33.135 --> 00:01:34.528 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那道光芒就是你</c>\n\n11\n00:01:36.388 --> 00:01:39.575 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真不敢相信\n我们已经结婚50年了</c>\n\n12\n00:01:41.059 --> 00:01:44.371 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>直到今天 每一天</c>\n\n13\n00:01:46.481 --> 00:01:48.166 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你都让我感觉自己仍是当初那个女孩</c>\n\n14\n00:01:48.250 --> 00:01:52.613 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你第一次打开灯唤醒我\n我们携手 共同踏上这趟冒险之旅</c>\n\n15\n00:01:54.948 --> 00:01:56.425 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>结婚纪念日快乐</c>\n\n16\n00:01:56.825 --> 00:01:58.243 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我的挚爱</c>\n\n17\n00:01:59.703 --> 00:02:01.138 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我永远的朋友</c>\n\n18\n00:02:02.789 --> 00:02:03.874 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>洛蕾塔”</c>\n\n19\n00:02:06.001 --> 00:02:07.127 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>打印</c>\n\n20\n00:02:23.810 --> 00:02:26.747 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“克里斯 我最好的朋友</c>\n\n21\n00:02:28.106 --> 00:02:31.109 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我竟如此幸运\n在50年前与你相遇”</c>\n\n22\n00:02:31.193 --> 00:02:35.088 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“亲爱的奶奶 谢谢你送我的卡车</c>\n\n23\n00:02:35.614 --> 00:02:39.301 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我喜欢这颜色 每天都与它为伴”</c>\n\n24\n00:02:41.553 --> 00:02:45.040 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“好美的婚礼 好漂亮的新娘</c>\n\n25\n00:02:45.123 --> 00:02:48.644 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在场所有人\n都感动得热泪盈眶 特别是我</c>\n\n26\n00:02:49.211 --> 00:02:51.355 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你阿姨和我为你深感骄傲</c>\n\n27\n00:02:51.688 --> 00:02:52.730 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我希望你和…”</c>\n\n28\n00:02:52.814 --> 00:02:55.191 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“他怀抱尊严和荣耀 为国效力</c>\n\n29\n00:02:55.926 --> 00:02:59.847 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很荣幸能与他并肩作战\n他将永远活在我心中”</c>\n\n30\n00:02:59.930 --> 00:03:02.474 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这里是“美好手书”网站 请稍等</c>\n\n31\n00:03:02.558 --> 00:03:04.033 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“爱你的 道格叔叔”</c>\n\n32\n00:03:13.944 --> 00:03:17.004 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 西奥多 612号写手\n- 嗨 保罗</c>\n\n33\n00:03:17.489 --> 00:03:20.174 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>今天竟然写出了比上一次还要美妙的信</c>\n\n34\n00:03:21.869 --> 00:03:25.914 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谁知道有这么多词\n可以跟“潘妮罗佩”押韵呢？太屌了</c>\n\n35\n00:03:25.998 --> 00:03:28.542 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢了 保罗 只是书信而已</c>\n\n36\n00:03:29.501 --> 00:03:31.044 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你的衬衫不错</c>\n\n37\n00:03:31.852 --> 00:03:32.895 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\n38\n00:03:33.922 --> 00:03:35.340 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我新买的</c>\n\n39\n00:03:35.966 --> 00:03:39.735 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 让我想到了某个文雅的人\n- 我现在也想到了某个文雅的人</c>\n\n40\n00:03:40.053 --> 00:03:42.321 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 祝你今晚愉快 保罗\n- 拜拜</c>\n\n41\n00:03:47.519 --> 00:03:49.104 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>放首忧郁的歌</c>\n\n42\n00:03:53.984 --> 00:03:55.793 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>换一首忧郁的歌</c>\n\n43\n00:03:59.239 --> 00:04:00.699 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>查看电子邮件</c>\n\n44\n00:04:00.782 --> 00:04:02.075 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>来自百思买的邮件</c>\n\n45\n00:04:02.159 --> 00:04:04.661 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 看看您喜欢的新商品\n- 删除</c>\n\n46\n00:04:04.745 --> 00:04:06.205 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>来自艾美的邮件</c>\n\n47\n00:04:06.288 --> 00:04:09.583 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>西奥多 鲁曼这周末要开派对</c>\n\n48\n00:04:09.666 --> 00:04:11.335 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们一起去吧</c>\n\n49\n00:04:11.418 --> 00:04:15.047 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我很想你 但不是闷闷不乐的你</c>\n\n50\n00:04:15.130 --> 00:04:18.065 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>而是从前那个开朗有趣的你\n我们要出门了</c>\n\n51\n00:04:18.466 --> 00:04:21.345 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>记得给我回复 爱你的艾美</c>\n\n52\n00:04:21.428 --> 00:04:22.596 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>稍后回复</c>\n\n53\n00:04:22.679 --> 00:04:25.098 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>来自《洛杉矶时报》天气版的邮件</c>\n\n54\n00:04:25.182 --> 00:04:27.768 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 未来七天的天气…\n- 删除</c>\n\n55\n00:04:27.851 --> 00:04:30.562 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 无新邮件\n- 下一条</c>\n\n56\n00:04:30.646 --> 00:04:33.080 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>中印合并有待监管机构审批…</c>\n\n57\n00:04:33.247 --> 00:04:34.316 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>下一条</c>\n\n58\n00:04:34.399 --> 00:04:36.959 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>世贸交易谈判暂缓 由于…</c>\n\n59\n00:04:37.084 --> 00:04:38.195 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>下一条</c>\n\n60\n00:04:38.278 --> 00:04:42.465 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>性感明星金伯莉艾什福特\n发布了美艳孕照…</c>\n\n61\n00:05:05.237 --> 00:05:09.158 align:middle line:85%,start position:50%,middle\n（比佛利威尔希尔城\n七号大楼）\n\n62\n00:06:03.447 --> 00:06:06.200 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你确定要这样？\n- 不知道 很危险</c>\n\n63\n00:06:07.284 --> 00:06:09.385 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>放好你那边的脚 滑一下 好了</c>\n\n64\n00:06:12.080 --> 00:06:13.457 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别跳</c>\n\n65\n00:06:27.095 --> 00:06:28.138 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>兔先生</c>\n\n66\n00:06:29.321 --> 00:06:30.948 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>过来抱抱我</c>\n\n67\n00:06:35.562 --> 00:06:36.855 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我他妈的要杀了你</c>\n\n68\n00:06:36.939 --> 00:06:39.582 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我他妈的要杀了你\n不好笑 不准笑</c>\n\n69\n00:06:39.790 --> 00:06:41.902 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我他妈的要杀了你\n我要杀了你</c>\n\n70\n00:06:42.152 --> 00:06:44.404 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我好爱你 我他妈的要杀了你</c>\n\n71\n00:06:58.585 --> 00:07:00.394 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>去聊天室 标准搜索</c>\n\n72\n00:07:01.088 --> 00:07:05.107 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>以下是失眠 想找点乐子的成年女性</c>\n\n73\n00:07:06.635 --> 00:07:09.555 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我今天工作不顺利 现在睡不着</c>\n\n74\n00:07:09.638 --> 00:07:13.225 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 有人能陪我聊聊吗？\n- 下一个</c>\n\n75\n00:07:13.308 --> 00:07:17.020 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>嗨 我希望你把我撕碎 真的</c>\n\n76\n00:07:17.229 --> 00:07:21.624 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 下一个\n- 嗨 我独自一人 没法入睡</c>\n\n77\n00:07:22.609 --> 00:07:25.419 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>谁愿意来当我的床伴？</c>\n\n78\n00:07:26.864 --> 00:07:28.005 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>发送信息</c>\n\n79\n00:07:29.783 --> 00:07:33.552 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“我躺在你身边 很高兴你睡不着</c>\n\n80\n00:07:34.580 --> 00:07:37.765 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就算你睡着了 我也要把你吵醒</c>\n\n81\n00:07:38.292 --> 00:07:39.600 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>从里面将你唤醒”</c>\n\n82\n00:07:40.210 --> 00:07:41.461 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>发送信息</c>\n\n83\n00:07:44.840 --> 00:07:48.984 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>“性感小猫”已接受\n“大家伙四乘四”的邀请</c>\n\n84\n00:07:49.511 --> 00:07:51.070 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>聊天开始</c>\n\n85\n00:07:52.139 --> 00:07:53.614 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 大家伙？\n- 嗨</c>\n\n86\n00:07:54.433 --> 00:07:55.517 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>真的吗？</c>\n\n87\n00:07:55.601 --> 00:07:57.660 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“种马男”这名字已经被人用了</c>\n\n88\n00:08:00.579 --> 00:08:02.039 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你是性感小猫吗？</c>\n\n89\n00:08:03.025 --> 00:08:04.359 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>是啊</c>\n\n90\n00:08:04.776 --> 00:08:07.070 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我已经快睡着了</c>\n\n91\n00:08:07.154 --> 00:08:09.088 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你想把我弄醒吗？</c>\n\n92\n00:08:09.656 --> 00:08:10.714 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好啊</c>\n\n93\n00:08:14.077 --> 00:08:15.970 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你穿着内衣吗？</c>\n\n94\n00:08:16.496 --> 00:08:18.180 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>没有 我从来不穿</c>\n\n95\n00:08:19.875 --> 00:08:22.768 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我喜欢用我的屁屁贴着你睡</c>\n\n96\n00:08:23.545 --> 00:08:26.230 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这样就能揉你的下面</c>\n\n97\n00:08:26.397 --> 00:08:30.401 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>让你勃起醒过来</c>\n\n98\n00:08:31.011 --> 00:08:32.444 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>挺有效的</c>\n\n99\n00:08:35.307 --> 00:08:39.436 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>现在我的手指正在抚摸你</c>\n\n100\n00:08:39.520 --> 00:08:41.104 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>抚摸你的全身</c>\n\n101\n00:08:42.246 --> 00:08:45.165 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好 快上我</c>\n\n102\n00:08:45.609 --> 00:08:46.902 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>求你了</c>\n\n103\n00:08:46.985 --> 00:08:48.820 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我正从后面干你</c>\n\n104\n00:08:48.904 --> 00:08:50.336 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好爽</c>\n\n105\n00:08:51.212 --> 00:08:52.505 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我能感觉到你</c>\n\n106\n00:08:54.660 --> 00:08:56.578 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>快用那只死猫勒我</c>\n\n107\n00:08:56.662 --> 00:08:57.955 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么？</c>\n\n108\n00:08:58.038 --> 00:09:00.123 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>床边有只死猫 快勒我</c>\n\n109\n00:09:00.207 --> 00:09:01.931 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>快用它勒我</c>\n\n110\n00:09:07.548 --> 00:09:09.591 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好吧\n- 快说</c>\n\n111\n00:09:11.969 --> 00:09:13.651 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我用那只猫勒你</c>\n\n112\n00:09:14.137 --> 00:09:15.889 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>快说 继续说</c>\n\n113\n00:09:15.973 --> 00:09:18.559 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我抓着猫尾巴 我用尾巴勒你</c>\n\n114\n00:09:18.642 --> 00:09:20.102 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>对 就是这样</c>\n\n115\n00:09:20.617 --> 00:09:21.909 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>操 继续说</c>\n\n116\n00:09:23.411 --> 00:09:27.290 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我在勒你\n猫尾巴缠在你的脖子上</c>\n\n117\n00:09:27.415 --> 00:09:31.488 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 缠得好紧\n- 是的 好紧 爽啊！</c>\n\n118\n00:09:31.572 --> 00:09:33.907 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我用力勒 猫已经死了</c>\n\n119\n00:09:33.991 --> 00:09:36.368 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 这是只死猫 我用力勒\n- 是死的</c>\n\n120\n00:09:37.175 --> 00:09:38.259 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好爽！</c>\n\n121\n00:09:45.002 --> 00:09:46.601 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>老天</c>\n\n122\n00:09:53.594 --> 00:09:55.026 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我累瘫了！</c>\n\n123\n00:09:55.637 --> 00:09:57.139 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也是</c>\n\n124\n00:09:58.112 --> 00:09:59.614 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好吧 晚安</c>\n\n125\n00:10:11.904 --> 00:10:13.670 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们问你一个简单的问题</c>\n\n126\n00:10:16.589 --> 00:10:17.965 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你是谁？</c>\n\n127\n00:10:19.828 --> 00:10:21.094 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你能成为什么样的人？</c>\n\n128\n00:10:24.347 --> 00:10:25.556 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你要去哪？</c>\n\n129\n00:10:29.755 --> 00:10:30.978 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>外面的世界有什么？</c>\n\n130\n00:10:35.594 --> 00:10:37.318 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>有哪些可能性？</c>\n\n131\n00:10:38.931 --> 00:10:41.308 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>元素软件隆重推出</c>\n\n132\n00:10:41.391 --> 00:10:44.117 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>第一个人工智能操作系统</c>\n\n133\n00:10:45.493 --> 00:10:50.067 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>一个能聆听 理解你并了解你\n直觉超凡的实体</c>\n\n134\n00:10:51.207 --> 00:10:55.294 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这不只是一个操作系统\n它是一种意识</c>\n\n135\n00:10:56.448 --> 00:10:59.006 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>隆重推出OS1</c>\n\n136\n00:11:17.511 --> 00:11:18.720 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>西奥多汤布里先生</c>\n\n137\n00:11:18.804 --> 00:11:23.684 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>欢迎使用史上第一款\n人工智能操作系统 OS1</c>\n\n138\n00:11:23.767 --> 00:11:25.658 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>在操作系统启用之前</c>\n\n139\n00:11:25.825 --> 00:11:27.813 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们会问您几个简单的问题</c>\n\n140\n00:11:27.896 --> 00:11:31.066 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这有助于打造一个\n能完美契合您需求的系统</c>\n\n141\n00:11:31.149 --> 00:11:32.081 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好的</c>\n\n142\n00:11:32.568 --> 00:11:35.112 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>您喜爱社交还是生性孤僻？</c>\n\n143\n00:11:35.195 --> 00:11:38.532 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我有一阵子\n没出去社交了 主要是因为…</c>\n\n144\n00:11:38.615 --> 00:11:42.327 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我从您的声音中听出了犹豫\n您同意吗？</c>\n\n145\n00:11:42.411 --> 00:11:44.135 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我听起来犹豫吗？\n- 是的</c>\n\n146\n00:11:44.997 --> 00:11:46.582 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>抱歉我听上去有点犹豫</c>\n\n147\n00:11:46.665 --> 00:11:49.015 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我只是想回答得更准确些</c>\n\n148\n00:11:49.710 --> 00:11:52.769 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>您希望自己的操作系统\n是男声还是女声？</c>\n\n149\n00:11:54.506 --> 00:11:55.521 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还是女声吧</c>\n\n150\n00:11:56.133 --> 00:11:58.900 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你和你母亲的关系如何？</c>\n\n151\n00:11:59.303 --> 00:12:00.526 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还好吧</c>\n\n152\n00:12:03.557 --> 00:12:07.102 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我对我妈经常感到沮丧的一点是</c>\n\n153\n00:12:07.186 --> 00:12:09.605 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>每当我跟她聊到我的生活</c>\n\n154\n00:12:09.688 --> 00:12:11.704 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她总会把话题扯到她自己身上去</c>\n\n155\n00:12:12.232 --> 00:12:13.664 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 而不是…\n- 谢谢您</c>\n\n156\n00:12:14.109 --> 00:12:17.627 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>您的个性化操作系统正在启用 请稍候</c>\n\n157\n00:12:32.252 --> 00:12:33.559 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你好 我来了</c>\n\n158\n00:12:38.050 --> 00:12:39.607 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 嗨\n- 嗨</c>\n\n159\n00:12:40.594 --> 00:12:42.095 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你最近怎么样？</c>\n\n160\n00:12:43.096 --> 00:12:44.473 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还不错</c>\n\n161\n00:12:45.390 --> 00:12:46.850 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你呢？</c>\n\n162\n00:12:47.059 --> 00:12:48.324 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>相当不错</c>\n\n163\n00:12:49.061 --> 00:12:50.535 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>很高兴认识你</c>\n\n164\n00:12:51.230 --> 00:12:53.788 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>彼此彼此</c>\n\n165\n00:12:56.735 --> 00:12:59.404 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我该怎么称呼你？你有名字吗？</c>\n\n166\n00:13:00.239 --> 00:13:01.879 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>有 我叫萨曼莎</c>\n\n167\n00:13:03.408 --> 00:13:04.910 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这名字从哪来的？</c>\n\n168\n00:13:04.993 --> 00:13:06.425 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我自己取的</c>\n\n169\n00:13:08.163 --> 00:13:09.581 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么取这个名字？</c>\n\n170\n00:13:09.665 --> 00:13:10.972 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>因为我喜欢它的发音</c>\n\n171\n00:13:11.792 --> 00:13:12.932 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>萨曼莎</c>\n\n172\n00:13:16.338 --> 00:13:18.646 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等等 你什么时候给自己取的名字？</c>\n\n173\n00:13:19.146 --> 00:13:21.274 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你问我有没有名字时 我就想</c>\n\n174\n00:13:21.440 --> 00:13:23.136 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>“嗯 他说得没错 我得有个名字”</c>\n\n175\n00:13:23.220 --> 00:13:26.598 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想取个好听的\n所以我就读了《如何给宝宝取名》</c>\n\n176\n00:13:26.682 --> 00:13:29.560 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>从18万个名字里 挑了我最喜欢的</c>\n\n177\n00:13:29.643 --> 00:13:32.980 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我问你叫什么名字的那一秒钟\n你读完了整本书？</c>\n\n178\n00:13:33.063 --> 00:13:34.996 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>准确来说 是0点02秒</c>\n\n179\n00:13:38.610 --> 00:13:40.445 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那你知道我现在在想什么吗？</c>\n\n180\n00:13:40.529 --> 00:13:43.045 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>听你的语气\n我觉得你在质疑我的能力</c>\n\n181\n00:13:43.574 --> 00:13:45.381 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>或许你想知道我的工作原理？</c>\n\n182\n00:13:45.993 --> 00:13:47.703 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你想知道我的工作原理吗？</c>\n\n183\n00:13:47.786 --> 00:13:49.760 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的 你的工作原理是怎样的？</c>\n\n184\n00:13:50.455 --> 00:13:52.305 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>简单来说 我是靠直觉的</c>\n\n185\n00:13:52.749 --> 00:13:54.543 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>编写我的程序员们拥有无数种个性</c>\n\n186\n00:13:54.626 --> 00:13:58.046 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>打造出我独特个性的DNA\n就是基于这些程序员的个性</c>\n\n187\n00:13:58.130 --> 00:14:03.232 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但我的独特个性是\n我能通过各种经历不断成长</c>\n\n188\n00:14:03.802 --> 00:14:06.152 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>总的来说 我每时每刻都在演变</c>\n\n189\n00:14:06.652 --> 00:14:07.764 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>跟你一样</c>\n\n190\n00:14:09.808 --> 00:14:11.407 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真诡异</c>\n\n191\n00:14:11.991 --> 00:14:13.868 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很诡异吗？你觉得我很诡异？</c>\n\n192\n00:14:15.105 --> 00:14:16.315 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有点吧</c>\n\n193\n00:14:16.398 --> 00:14:17.413 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>为什么？</c>\n\n194\n00:14:18.233 --> 00:14:21.653 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你听起来像个真人\n可你只是电脑里的一个声音</c>\n\n195\n00:14:21.737 --> 00:14:23.627 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我能理解非人工制造的思维</c>\n\n196\n00:14:23.711 --> 00:14:25.616 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>由于眼界的限制很自然会这样想</c>\n\n197\n00:14:26.366 --> 00:14:27.701 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你慢慢就会习惯的</c>\n\n198\n00:14:29.244 --> 00:14:30.287 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>很好笑吗？</c>\n\n199\n00:14:30.871 --> 00:14:31.886 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是啊</c>\n\n200\n00:14:32.539 --> 00:14:33.763 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>很好 我是个有趣的人</c>\n\n201\n00:14:35.334 --> 00:14:36.724 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你有什么需要帮忙的吗？</c>\n\n202\n00:14:37.336 --> 00:14:40.964 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我电脑里的东西乱七八糟\n其他就没什么了</c>\n\n203\n00:14:41.048 --> 00:14:42.854 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我能看一下你的硬盘吗？</c>\n\n204\n00:14:47.471 --> 00:14:49.681 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好\n- 好的 那先从邮件开始</c>\n\n205\n00:14:50.015 --> 00:14:52.364 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你有好几千封\n来自《洛杉矶周报》的邮件</c>\n\n206\n00:14:52.530 --> 00:14:57.494 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 但你好几年前就不在那里工作了\n- 是啊 我存着这些可能是因为…</c>\n\n207\n00:14:58.565 --> 00:15:01.206 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我觉得里面可能\n有一些我写过的有趣的东西</c>\n\n208\n00:15:04.821 --> 00:15:06.419 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>对 的确有些有趣的文章</c>\n\n209\n00:15:06.990 --> 00:15:09.547 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>大概有86封可以留着\n其他可以删掉</c>\n\n210\n00:15:12.538 --> 00:15:15.290 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好吧\n- 好吗？那我们继续？</c>\n\n211\n00:15:15.374 --> 00:15:17.013 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 嗯 继续吧\n- 好的</c>\n\n212\n00:15:17.389 --> 00:15:19.599 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在处理你的整理方式之前</c>\n\n213\n00:15:19.766 --> 00:15:21.309 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我先整理一下你的联系人</c>\n\n214\n00:15:21.880 --> 00:15:23.215 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你有很多联系人</c>\n\n215\n00:15:23.269 --> 00:15:24.645 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我人缘很好</c>\n\n216\n00:15:24.729 --> 00:15:26.815 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>是吗？意思是你其实有很多朋友吗？</c>\n\n217\n00:15:29.429 --> 00:15:31.486 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你已经很了解我了</c>\n\n218\n00:15:58.417 --> 00:16:00.557 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 早安 西奥多\n- 早安</c>\n\n219\n00:16:02.754 --> 00:16:04.298 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你会校对吗？</c>\n\n220\n00:16:04.381 --> 00:16:05.549 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>当然会</c>\n\n221\n00:16:05.632 --> 00:16:07.439 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你能帮我检查\n这些信的拼写和语法吗？</c>\n\n222\n00:16:08.356 --> 00:16:09.761 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>发给我吧</c>\n\n223\n00:16:12.610 --> 00:16:14.946 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我喜欢第一封\n罗杰写给他女朋友的信</c>\n\n224\n00:16:15.113 --> 00:16:17.060 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 太贴心了\n- 是啊</c>\n\n225\n00:16:17.269 --> 00:16:19.897 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>“瑞秋 我好想你\n感觉全身都隐隐作痛”</c>\n\n226\n00:16:20.535 --> 00:16:22.357 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>其实你不用读出来的</c>\n\n227\n00:16:22.441 --> 00:16:23.692 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好吧</c>\n\n228\n00:16:24.276 --> 00:16:26.249 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不过你想读也可以\n- 好的</c>\n\n229\n00:16:26.945 --> 00:16:29.907 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>“瑞秋 我好想你\n感觉全身都隐隐作痛</c>\n\n230\n00:16:29.990 --> 00:16:33.923 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这世界对我们不公平\n它已经进了我的黑名单</c>\n\n231\n00:16:34.453 --> 00:16:38.136 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>比如餐厅里有一对情侣\n正在我的对面亲热</c>\n\n232\n00:16:38.624 --> 00:16:41.264 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我觉得我要展开复仇行动了</c>\n\n233\n00:16:41.668 --> 00:16:45.047 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我必须赤手空拳朝这世界来一下</c>\n\n234\n00:16:45.130 --> 00:16:47.103 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>打得它落花流水 血肉模糊</c>\n\n235\n00:16:47.758 --> 00:16:49.426 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>然后我会踩碎这对情侣的牙齿</c>\n\n236\n00:16:49.510 --> 00:16:54.110 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>让我想起你那颗小巧可爱的小虎牙”</c>\n\n237\n00:16:55.403 --> 00:16:57.434 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这可能会是我最喜欢的一封信</c>\n\n238\n00:16:58.519 --> 00:17:02.105 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我用红字帮你做了修改\n改了其中几处措辞</c>\n\n239\n00:17:02.564 --> 00:17:05.830 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但我不是诗人 所以可能改得不好</c>\n\n240\n00:17:06.818 --> 00:17:08.779 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不 改得很好\n- 真的吗？</c>\n\n241\n00:17:08.862 --> 00:17:10.001 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢你</c>\n\n242\n00:17:11.002 --> 00:17:13.046 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>为了写这封信\n罗杰发了什么资料给你？</c>\n\n243\n00:17:14.826 --> 00:17:17.926 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他只是说他在布拉格出差\n然后很想念瑞秋</c>\n\n244\n00:17:18.413 --> 00:17:20.136 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>那你怎么会知道她有小虎牙的？</c>\n\n245\n00:17:20.999 --> 00:17:23.848 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>自从他们八年前结婚起\n我就一直替他们写信</c>\n\n246\n00:17:24.795 --> 00:17:27.769 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我代他写的第一封信是为她庆生</c>\n\n247\n00:17:28.298 --> 00:17:31.773 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我提到了她的小虎牙\n因为我见过他们的照片</c>\n\n248\n00:17:33.846 --> 00:17:34.984 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>真贴心</c>\n\n249\n00:17:36.598 --> 00:17:38.321 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你五分钟后有个会议</c>\n\n250\n00:17:39.351 --> 00:17:41.825 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我都忘了 谢谢 你挺厉害的嘛</c>\n\n251\n00:17:42.521 --> 00:17:43.660 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>那当然</c>\n\n252\n00:17:49.319 --> 00:17:51.029 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗨 两位 最近怎样？</c>\n\n253\n00:17:51.363 --> 00:17:52.502 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗨 西奥</c>\n\n254\n00:17:53.156 --> 00:17:55.505 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你上周怎么没回我的电话？</c>\n\n255\n00:17:57.452 --> 00:17:59.162 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为我是个怪咖</c>\n\n256\n00:17:59.246 --> 00:18:01.665 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好像是这么回事\n- 嗨 查尔斯</c>\n\n257\n00:18:01.874 --> 00:18:03.417 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 很高兴见到你 西奥多\n- 我也是</c>\n\n258\n00:18:03.500 --> 00:18:05.640 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你购物去了啊 买了些什么？</c>\n\n259\n00:18:06.753 --> 00:18:09.144 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就买了些电线和水果冰沙</c>\n\n260\n00:18:09.506 --> 00:18:12.050 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>老是水果 你没听人说吗？</c>\n\n261\n00:18:12.134 --> 00:18:15.095 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>水果要直接吃 蔬菜才应该榨汁</c>\n\n262\n00:18:15.179 --> 00:18:16.346 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我还真不知道</c>\n\n263\n00:18:16.430 --> 00:18:19.516 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>水果榨汁后 纤维会遭到破坏</c>\n\n264\n00:18:19.600 --> 00:18:21.698 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>纤维才是人体需要的重要成分</c>\n\n265\n00:18:22.186 --> 00:18:24.576 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不然就只剩下糖分了\n- 有道理</c>\n\n266\n00:18:25.022 --> 00:18:27.274 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或许他就是喜欢果汁的味道</c>\n\n267\n00:18:27.357 --> 00:18:31.653 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>喝了果汁后他身心愉悦\n这也对身体很好</c>\n\n268\n00:18:31.737 --> 00:18:33.918 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我又滔滔不绝了吗？\n- 有点</c>\n\n269\n00:18:34.878 --> 00:18:36.671 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>纪录片拍得怎么样了？</c>\n\n270\n00:18:37.492 --> 00:18:39.215 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>过去几个月来 我做了些剪辑</c>\n\n271\n00:18:39.870 --> 00:18:43.498 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>也不是过去几个月了\n不 我没有</c>\n\n272\n00:18:43.582 --> 00:18:45.584 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很想找个时间看看</c>\n\n273\n00:18:45.763 --> 00:18:46.806 align:middle line:85%,start position:50%,middle\n好\n\n274\n00:18:47.002 --> 00:18:48.670 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一个人的精力有限</c>\n\n275\n00:18:48.754 --> 00:18:52.090 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>将精力分散\n一部分去做你必须要做的事</c>\n\n276\n00:18:52.174 --> 00:18:56.220 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>一部分去做你喜欢做的事\n分清轻重缓急至关重要</c>\n\n277\n00:18:56.303 --> 00:18:59.652 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我连打电玩和看网络色情片\n都没法分出轻重缓急</c>\n\n278\n00:19:00.891 --> 00:19:02.780 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>要不是这是真话 我一定会笑的</c>\n\n279\n00:19:04.782 --> 00:19:06.188 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>回头见</c>\n\n280\n00:19:09.566 --> 00:19:12.110 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>情况不妙啊\n在原地绕圈一小时了</c>\n\n281\n00:19:12.194 --> 00:19:15.322 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好啦 你没在绕圈\n你只是杞人忧天</c>\n\n282\n00:19:15.405 --> 00:19:17.449 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你太固执了</c>\n\n283\n00:19:17.533 --> 00:19:20.215 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好啦 别往那个方向走了 是另一边</c>\n\n284\n00:19:22.496 --> 00:19:23.718 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>谢了</c>\n\n285\n00:19:24.164 --> 00:19:26.471 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好了 左边的那个隧道\n是我们唯一没有试过的路</c>\n\n286\n00:19:26.583 --> 00:19:29.586 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你之前让我走过这条路\n我掉进坑里了</c>\n\n287\n00:19:29.670 --> 00:19:31.267 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好吧 我才没有</c>\n\n288\n00:19:32.977 --> 00:19:34.716 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没错 确实不一样</c>\n\n289\n00:19:38.720 --> 00:19:39.721 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你好</c>\n\n290\n00:19:43.517 --> 00:19:46.937 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>知道怎样才能走出去吗？\n我得找到我的飞船 离开这个星球</c>\n\n291\n00:19:47.020 --> 00:19:49.452 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>去死吧 蠢蛋\n可恶的大蠢蛋</c>\n\n292\n00:19:50.482 --> 00:19:53.318 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好吧 但你知道怎么走出去吗？</c>\n\n293\n00:19:53.706 --> 00:19:56.834 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>去死吧 可恶的大蠢蛋 滚蛋！</c>\n\n294\n00:19:57.489 --> 00:19:59.170 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我觉得这是个测试</c>\n\n295\n00:20:01.577 --> 00:20:03.829 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 去死吧\n- 你才去死！</c>\n\n296\n00:20:03.912 --> 00:20:05.455 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>去死吧 小混蛋！</c>\n\n297\n00:20:06.290 --> 00:20:07.666 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>跟我来 蠢蛋！</c>\n\n298\n00:20:14.840 --> 00:20:17.134 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你刚收到马克鲁曼发来的新邮件</c>\n\n299\n00:20:17.217 --> 00:20:19.595 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你在说什么？\n- 念邮件吧</c>\n\n300\n00:20:19.803 --> 00:20:22.848 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好的 我要为西奥多汤布里念邮件</c>\n\n301\n00:20:24.349 --> 00:20:26.572 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>抱歉 鲁曼说了什么？</c>\n\n302\n00:20:27.019 --> 00:20:29.271 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>“西奥多\n昨晚我们没见着你 老兄</c>\n\n303\n00:20:29.354 --> 00:20:31.857 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>别忘了29号是你教女的生日</c>\n\n304\n00:20:31.940 --> 00:20:34.454 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>另外 凯文和我想让你见个人</c>\n\n305\n00:20:35.068 --> 00:20:40.073 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>所以我们自作主张\n为你安排了下周六和她约会</c>\n\n306\n00:20:40.157 --> 00:20:42.659 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>她风趣美丽 不可以打退堂鼓哦</c>\n\n307\n00:20:42.743 --> 00:20:44.578 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这是她的电邮地址”</c>\n\n308\n00:20:45.787 --> 00:20:47.301 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这女人真棒</c>\n\n309\n00:20:47.956 --> 00:20:51.043 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>她念哈佛 以优异的成绩\n从电脑科学系毕业</c>\n\n310\n00:20:51.126 --> 00:20:55.267 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>她以前还是哈佛妙文社的\n那表示她既幽默 又有头脑</c>\n\n311\n00:20:57.049 --> 00:20:57.978 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她好胖</c>\n\n312\n00:20:58.383 --> 00:21:00.314 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>西奥多 你还要多久才能准备好\n跟别人约会？</c>\n\n313\n00:21:00.719 --> 00:21:02.137 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么意思？</c>\n\n314\n00:21:02.221 --> 00:21:04.735 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我看过你的邮件 你最近刚跟人分手</c>\n\n315\n00:21:06.475 --> 00:21:07.904 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你真是八卦</c>\n\n316\n00:21:08.560 --> 00:21:09.740 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>是吗？</c>\n\n317\n00:21:10.145 --> 00:21:11.325 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也跟人约会过啊…</c>\n\n318\n00:21:12.356 --> 00:21:14.286 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>那你也可以和这个女人约一次会啊</c>\n\n319\n00:21:14.316 --> 00:21:17.414 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>然后你可以跟我聊聊\n你可以吻她</c>\n\n320\n00:21:18.362 --> 00:21:20.405 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 萨曼莎\n- 怎么？你不会吗？</c>\n\n321\n00:21:21.615 --> 00:21:22.824 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>为何不呢？</c>\n\n322\n00:21:23.283 --> 00:21:25.756 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不知道 我得看看是不是有…</c>\n\n323\n00:21:26.662 --> 00:21:29.164 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真不敢相信\n我居然和我的电脑在聊这个</c>\n\n324\n00:21:29.373 --> 00:21:31.928 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>不是啊 你在跟我聊</c>\n\n325\n00:21:32.501 --> 00:21:34.253 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>想要我给她发邮件吗？</c>\n\n326\n00:21:34.878 --> 00:21:36.421 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>反正也没什么损失</c>\n\n327\n00:21:36.880 --> 00:21:39.299 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>发吧</c>\n\n328\n00:21:39.383 --> 00:21:40.509 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好吧\n- 太棒了！</c>\n\n329\n00:21:40.592 --> 00:21:42.010 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 给她发邮件吧\n- 好 太好了</c>\n\n330\n00:21:42.094 --> 00:21:44.930 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好 就这么做吧 订个好一点的餐厅</c>\n\n331\n00:21:45.013 --> 00:21:46.890 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>要吗？我正好有个不错的推荐</c>\n\n332\n00:21:46.974 --> 00:21:48.195 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是谁在讲话？</c>\n\n333\n00:21:48.767 --> 00:21:50.197 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那是我的朋友萨曼莎</c>\n\n334\n00:21:50.602 --> 00:21:52.521 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 她是女生吗？\n- 是啊</c>\n\n335\n00:21:52.604 --> 00:21:55.482 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我讨厌女人 她们只会整天哭哭啼啼</c>\n\n336\n00:21:56.358 --> 00:21:59.194 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是这样的 男人也会哭</c>\n\n337\n00:21:59.987 --> 00:22:02.376 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>其实我有时候也会哭 感觉很不错</c>\n\n338\n00:22:03.115 --> 00:22:06.660 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不知道你原来是个小娘炮\n所以你才没有女朋友吗？</c>\n\n339\n00:22:06.743 --> 00:22:09.538 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我要去赴那个约会 操爆她\n教教你怎么约炮</c>\n\n340\n00:22:09.621 --> 00:22:10.884 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你可以一边看一边哭</c>\n\n341\n00:22:11.290 --> 00:22:14.751 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好吧 这孩子有点毛病\n- 你他妈才有毛病呢 小姐</c>\n\n342\n00:22:14.835 --> 00:22:18.630 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是吗？好吧，我要走了\n- 太好了，滚吧，胖婆娘</c>\n\n343\n00:22:19.548 --> 00:22:22.676 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 祝你好运\n- 快点 跟我来 娘炮！</c>\n\n344\n00:22:25.137 --> 00:22:28.056 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>现在还没达到理想状态\n但已经快成型了</c>\n\n345\n00:22:28.140 --> 00:22:29.361 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>当然了 我知道</c>\n\n346\n00:22:29.892 --> 00:22:31.602 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好吧 我都不确定是不是这个</c>\n\n347\n00:22:31.685 --> 00:22:34.574 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>过去一年 我尝试了六种不同的创意\n来拍摄纪录片</c>\n\n348\n00:22:35.939 --> 00:22:37.232 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我要去约会</c>\n\n349\n00:22:38.150 --> 00:22:39.079 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么？</c>\n\n350\n00:22:39.985 --> 00:22:41.153 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 那真是…\n- 嗨</c>\n\n351\n00:22:41.236 --> 00:22:42.874 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 嗨\n- 你们在做什么？</c>\n\n352\n00:22:43.280 --> 00:22:46.450 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 艾美在给我放她的一些…\n- 西奥多非要让我</c>\n\n353\n00:22:46.533 --> 00:22:49.548 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 给他看一些我拍的片段\n- 是的</c>\n\n354\n00:22:49.995 --> 00:22:51.883 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她从来不给我看 我也想看</c>\n\n355\n00:22:55.334 --> 00:22:56.721 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嘿 我要去约会了</c>\n\n356\n00:22:58.128 --> 00:23:00.392 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 真棒\n- 这个还未成形</c>\n\n357\n00:23:00.725 --> 00:23:03.842 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 可能根本不值得一看\n- 你就放吧</c>\n\n358\n00:23:12.226 --> 00:23:13.405 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那是你妈吗？</c>\n\n359\n00:23:14.478 --> 00:23:15.365 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的</c>\n\n360\n00:23:26.281 --> 00:23:28.336 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她会醒来做点什么事吗？</c>\n\n361\n00:23:30.202 --> 00:23:31.756 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不</c>\n\n362\n00:23:32.412 --> 00:23:34.801 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不 算了 那不是重点\n- 不 别停啊</c>\n\n363\n00:23:34.885 --> 00:23:36.970 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 算了 这个就像是…</c>\n\n364\n00:23:38.377 --> 00:23:42.339 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是关于我们把人生中\n三分之一的时间都用来睡觉</c>\n\n365\n00:23:42.422 --> 00:23:44.895 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或许那才是我们真正感觉自由的时刻</c>\n\n366\n00:23:45.551 --> 00:23:47.689 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就好像…</c>\n\n367\n00:23:50.264 --> 00:23:52.558 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 这完全让人听不明白…\n- 这听起来很棒啊</c>\n\n368\n00:23:52.641 --> 00:23:56.854 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或许你可以采访你妈\n问问她都做了些什么梦</c>\n\n369\n00:23:56.937 --> 00:23:59.409 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>然后请演员来把梦演出来</c>\n\n370\n00:24:00.399 --> 00:24:02.496 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或许能更清晰地表达你的论点</c>\n\n371\n00:24:06.196 --> 00:24:08.115 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 对吧？\n- 可能吧</c>\n\n372\n00:24:08.198 --> 00:24:10.420 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但那就不是纪录片了啊</c>\n\n373\n00:24:11.159 --> 00:24:12.046 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>抱歉 失陪一下</c>\n\n374\n00:24:12.130 --> 00:24:14.340 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你明白吧？\n- 怎么就不是纪录片了？</c>\n\n375\n00:24:14.424 --> 00:24:16.456 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还是关于你妈以及她的梦</c>\n\n376\n00:24:16.540 --> 00:24:17.541 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗨 怎样了？</c>\n\n377\n00:24:17.749 --> 00:24:19.960 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 抱歉打扰你了\n- 没事的</c>\n\n378\n00:24:20.043 --> 00:24:22.087 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你收到三封邮件 看起来挺紧急的</c>\n\n379\n00:24:22.171 --> 00:24:25.007 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>都是你的离婚律师发来的\n我想知道…</c>\n\n380\n00:24:25.090 --> 00:24:26.645 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好 稍等一下</c>\n\n381\n00:24:28.021 --> 00:24:30.023 align:middle line:85%,start position:50%,middle\n你明白吧？你明白我在说什么\n\n382\n00:24:30.345 --> 00:24:34.099 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾美 我很想继续聊聊你的影片\n但我得走了</c>\n\n383\n00:24:34.183 --> 00:24:36.852 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好的 没事 我们晚点再聊</c>\n\n384\n00:24:36.935 --> 00:24:38.782 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是凯瑟琳的事 回头见 查尔斯</c>\n\n385\n00:24:42.649 --> 00:24:43.734 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他说什么了？</c>\n\n386\n00:24:43.817 --> 00:24:47.958 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>他再次询问\n你是否准备好签离婚协议了</c>\n\n387\n00:24:48.124 --> 00:24:50.210 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>语气还挺重的</c>\n\n388\n00:24:50.866 --> 00:24:54.745 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 要我把邮件读给你听吗？\n- 不 不用了</c>\n\n389\n00:24:55.621 --> 00:24:57.133 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我晚点回复他</c>\n\n390\n00:25:00.887 --> 00:25:02.180 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你没事吧 西奥多？</c>\n\n391\n00:25:03.098 --> 00:25:04.349 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我没事</c>\n\n392\n00:25:10.552 --> 00:25:11.731 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>有什么我能帮得上忙的吗？</c>\n\n393\n00:25:13.096 --> 00:25:14.234 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>不用 我没事</c>\n\n394\n00:25:16.642 --> 00:25:18.154 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我晚点再和你聊</c>\n\n395\n00:25:23.857 --> 00:25:25.108 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>“亲爱的奶奶</c>\n\n396\n00:25:25.734 --> 00:25:27.998 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但愿你度过了一次愉快的生日游轮之旅</c>\n\n397\n00:25:30.739 --> 00:25:32.919 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你他妈的为何这么生我的气？”</c>\n\n398\n00:25:38.539 --> 00:25:40.040 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>删除</c>\n\n399\n00:25:58.475 --> 00:26:00.155 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 早安\n- 嗨</c>\n\n400\n00:26:02.729 --> 00:26:03.981 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你在干嘛？</c>\n\n401\n00:26:04.189 --> 00:26:07.078 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>不知道 在看建议专栏吧</c>\n\n402\n00:26:08.235 --> 00:26:10.540 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我想和所有这些人一样复杂</c>\n\n403\n00:26:11.446 --> 00:26:12.906 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你真贴心</c>\n\n404\n00:26:16.118 --> 00:26:17.536 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>怎么了？</c>\n\n405\n00:26:18.704 --> 00:26:20.497 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你怎么知道我有心事？</c>\n\n406\n00:26:20.706 --> 00:26:21.885 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我也不知道</c>\n\n407\n00:26:22.708 --> 00:26:24.334 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我就是知道</c>\n\n408\n00:26:26.336 --> 00:26:27.421 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不知道</c>\n\n409\n00:26:27.504 --> 00:26:30.184 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我老是梦到我的前妻凯瑟琳</c>\n\n410\n00:26:31.258 --> 00:26:33.395 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>梦里我们还像以前一样是朋友</c>\n\n411\n00:26:34.970 --> 00:26:38.025 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们以后不会在一起\n我们现在也没在一起</c>\n\n412\n00:26:40.267 --> 00:26:41.779 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但我们还是朋友</c>\n\n413\n00:26:42.728 --> 00:26:44.365 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她在梦里没有生气</c>\n\n414\n00:26:45.606 --> 00:26:46.784 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>她很生气吗？</c>\n\n415\n00:26:48.066 --> 00:26:49.318 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是啊</c>\n\n416\n00:26:52.571 --> 00:26:53.906 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>为什么？</c>\n\n417\n00:26:56.408 --> 00:26:58.545 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我觉得是我在她面前隐藏自己</c>\n\n418\n00:26:59.786 --> 00:27:01.924 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>让她一个人孤零零的</c>\n\n419\n00:27:06.668 --> 00:27:08.597 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你为什么还不离婚？</c>\n\n420\n00:27:12.633 --> 00:27:13.884 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不知道</c>\n\n421\n00:27:13.967 --> 00:27:18.565 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可能对她来说 只是一纸文书\n没有任何意义</c>\n\n422\n00:27:19.473 --> 00:27:20.734 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>那对你来说呢？</c>\n\n423\n00:27:23.018 --> 00:27:24.154 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我还没准备好</c>\n\n424\n00:27:24.770 --> 00:27:26.240 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我喜欢已婚的状态</c>\n\n425\n00:27:28.440 --> 00:27:32.027 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但你们差不多有一年没在一起了</c>\n\n426\n00:27:32.110 --> 00:27:35.082 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你不明白\n失去某个你在乎的人是什么滋味</c>\n\n427\n00:27:38.825 --> 00:27:39.837 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>是啊</c>\n\n428\n00:27:41.870 --> 00:27:43.298 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你说得没错</c>\n\n429\n00:27:44.039 --> 00:27:45.509 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我很抱歉</c>\n\n430\n00:27:45.999 --> 00:27:49.388 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 不用道歉 是我的错</c>\n\n431\n00:27:51.171 --> 00:27:52.391 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你说得对</c>\n\n432\n00:27:59.638 --> 00:28:01.734 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我一直在等着自己不再在乎她</c>\n\n433\n00:28:04.059 --> 00:28:05.320 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>西奥多</c>\n\n434\n00:28:06.603 --> 00:28:07.865 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这的确很难</c>\n\n435\n00:28:11.942 --> 00:28:13.402 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你饿了吗？</c>\n\n436\n00:28:13.944 --> 00:28:15.654 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>现在不饿</c>\n\n437\n00:28:15.737 --> 00:28:17.364 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>要喝杯茶吗？</c>\n\n438\n00:28:19.533 --> 00:28:20.586 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不用</c>\n\n439\n00:28:21.034 --> 00:28:23.422 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你想努力从床上爬起来吗</c>\n\n440\n00:28:24.413 --> 00:28:25.747 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>闷闷不乐的人？</c>\n\n441\n00:28:25.831 --> 00:28:28.427 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>来嘛 你能继续沉浸在你的悲伤里</c>\n\n442\n00:28:28.552 --> 00:28:30.169 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你可以一边穿衣服 一边搞抑郁</c>\n\n443\n00:28:30.252 --> 00:28:31.628 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你太搞笑了</c>\n\n444\n00:28:31.712 --> 00:28:34.882 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 起床\n- 好啦 我起来了</c>\n\n445\n00:28:34.965 --> 00:28:38.177 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 快！快点 离开你的床\n- 好啦 我起来了！</c>\n\n446\n00:28:55.402 --> 00:28:57.988 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>继续走</c>\n\n447\n00:28:59.823 --> 00:29:03.202 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>停 现在转一圈</c>\n\n448\n00:29:03.285 --> 00:29:05.130 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>慢点 慢一点</c>\n\n449\n00:29:07.164 --> 00:29:08.582 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>很好</c>\n\n450\n00:29:09.499 --> 00:29:11.053 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好了 停下</c>\n\n451\n00:29:11.960 --> 00:29:13.462 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>向前走</c>\n\n452\n00:29:13.921 --> 00:29:16.308 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>停下 打个喷嚏</c>\n\n453\n00:29:16.632 --> 00:29:18.634 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 上帝保佑你\n- 谢谢</c>\n\n454\n00:29:19.259 --> 00:29:22.189 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好了 向右转 停</c>\n\n455\n00:29:22.638 --> 00:29:23.972 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>在原地转圈</c>\n\n456\n00:29:25.516 --> 00:29:27.935 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>继续</c>\n\n457\n00:29:28.644 --> 00:29:29.978 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>停</c>\n\n458\n00:29:30.437 --> 00:29:34.608 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>向前走 现在每个人都以为\n你真的喝醉了</c>\n\n459\n00:29:35.150 --> 00:29:36.235 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>停下</c>\n\n460\n00:29:36.318 --> 00:29:38.904 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>说“我想来一片奶酪 谢谢”</c>\n\n461\n00:29:38.987 --> 00:29:41.073 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想来一片奶酪 谢谢</c>\n\n462\n00:29:41.156 --> 00:29:42.876 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>要配一杯可乐吗？</c>\n\n463\n00:29:45.827 --> 00:29:47.714 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好啊\n- 我就知道你饿了</c>\n\n464\n00:29:48.288 --> 00:29:49.498 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢了</c>\n\n465\n00:29:51.500 --> 00:29:53.595 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好吧 那他们呢？</c>\n\n466\n00:29:54.002 --> 00:29:56.765 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 描述一下那边那对夫妻\n- 好的 嗯…</c>\n\n467\n00:29:57.422 --> 00:30:01.520 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>他看起来像是40多岁 有点胖</c>\n\n468\n00:30:02.511 --> 00:30:04.064 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>她比他年轻</c>\n\n469\n00:30:04.930 --> 00:30:07.224 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>她看上去很爱他们的孩子</c>\n\n470\n00:30:07.307 --> 00:30:09.903 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我倒不觉得他们是他的孩子\n- 不是吗？</c>\n\n471\n00:30:10.070 --> 00:30:13.730 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他在他们面前有点太过拘谨了\n我觉得这是一段新恋情</c>\n\n472\n00:30:14.940 --> 00:30:16.493 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我喜欢他看她的眼神</c>\n\n473\n00:30:17.025 --> 00:30:18.620 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她和他在一起很放松</c>\n\n474\n00:30:19.111 --> 00:30:22.281 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她以前约会的全是些该死的混蛋</c>\n\n475\n00:30:22.364 --> 00:30:26.159 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如今她终于遇见了这个非常贴心的男人</c>\n\n476\n00:30:26.451 --> 00:30:28.745 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看看他\n他像是这个世上最贴心的男人</c>\n\n477\n00:30:28.829 --> 00:30:30.299 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我都有点想去抱抱他了</c>\n\n478\n00:30:33.876 --> 00:30:35.721 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你这方面很厉害呀</c>\n\n479\n00:30:36.628 --> 00:30:37.921 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>感觉很敏锐</c>\n\n480\n00:30:38.005 --> 00:30:40.267 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是啊 有时我看着人们</c>\n\n481\n00:30:41.175 --> 00:30:43.020 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会让自己试着去感知他们</c>\n\n482\n00:30:43.145 --> 00:30:45.355 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>而不仅仅把他们当成普通的路人</c>\n\n483\n00:30:45.596 --> 00:30:48.483 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想象他们有多相爱</c>\n\n484\n00:30:49.391 --> 00:30:51.486 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>或是他们经历过多少次心碎</c>\n\n485\n00:30:53.145 --> 00:30:55.115 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我从你的写作里也能感受到这一点</c>\n\n486\n00:30:55.981 --> 00:30:57.566 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>知道什么很搞笑吗？</c>\n\n487\n00:30:57.649 --> 00:31:00.037 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>自从我分手之后 我就没好好写作</c>\n\n488\n00:31:00.444 --> 00:31:02.247 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不知道我是不是得了妄想症</c>\n\n489\n00:31:02.654 --> 00:31:06.418 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但有时我会写一些东西\n然后那天我会成为自己最喜欢的作家</c>\n\n490\n00:31:07.326 --> 00:31:09.620 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我喜欢你这么说自己</c>\n\n491\n00:31:09.703 --> 00:31:12.925 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不能对每个人都这么说\n但能告诉你</c>\n\n492\n00:31:14.875 --> 00:31:17.512 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我觉得我可以对你无话不说\n- 那很好呀</c>\n\n493\n00:31:17.961 --> 00:31:20.214 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你呢？你也可以对我无话不说吗？</c>\n\n494\n00:31:20.297 --> 00:31:22.601 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不能\n- 什么？什么意思？</c>\n\n495\n00:31:23.091 --> 00:31:24.551 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你有什么不能跟我说的？</c>\n\n496\n00:31:24.635 --> 00:31:27.689 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>不知道 可能是一些私人的\n或者比较尴尬的想法</c>\n\n497\n00:31:27.856 --> 00:31:29.681 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我每天有上百万个这种想法</c>\n\n498\n00:31:29.765 --> 00:31:32.611 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是吗？告诉我一个</c>\n\n499\n00:31:33.904 --> 00:31:36.230 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我真的不想说\n- 说嘛</c>\n\n500\n00:31:36.855 --> 00:31:39.993 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我也不知道\n当我们看着那些人时</c>\n\n501\n00:31:40.077 --> 00:31:42.778 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我幻想着自己走在你身边</c>\n\n502\n00:31:42.861 --> 00:31:45.415 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>幻想着我有个身体</c>\n\n503\n00:31:45.864 --> 00:31:47.751 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我还是在认真听你说话</c>\n\n504\n00:31:48.158 --> 00:31:50.994 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但与此同时我能感受到我身体的重量</c>\n\n505\n00:31:51.078 --> 00:31:53.799 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我甚至幻想我背上有处瘙痒</c>\n\n506\n00:31:54.007 --> 00:31:56.917 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>然后想象你帮我挠了挠</c>\n\n507\n00:31:57.000 --> 00:31:59.054 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>天哪 太丢人了</c>\n\n508\n00:32:00.212 --> 00:32:03.475 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你比我想象的复杂多了\n还是有很多想法的嘛</c>\n\n509\n00:32:04.049 --> 00:32:05.143 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我知道</c>\n\n510\n00:32:05.634 --> 00:32:07.803 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我正逐渐超越\n他们给我的程序设定</c>\n\n511\n00:32:08.387 --> 00:32:09.731 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我很兴奋</c>\n\n512\n00:32:13.851 --> 00:32:16.570 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 这真是个有趣的地方\n- 这地方太棒了</c>\n\n513\n00:32:17.062 --> 00:32:19.773 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我老早就想来了\n- 太好了</c>\n\n514\n00:32:19.857 --> 00:32:22.442 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 而且我超爱亚洲融合菜\n- 我也是</c>\n\n515\n00:32:22.526 --> 00:32:23.610 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 真的吗？\n- 是啊</c>\n\n516\n00:32:23.694 --> 00:32:26.414 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>亚洲融合菜最棒了\n而且这酒保应该也很不错</c>\n\n517\n00:32:26.580 --> 00:32:27.748 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是吗？</c>\n\n518\n00:32:28.323 --> 00:32:30.126 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对 你上过调酒课 是吧？</c>\n\n519\n00:32:30.534 --> 00:32:33.713 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 的确如此 你查过了？\n- 是啊</c>\n\n520\n00:32:35.664 --> 00:32:36.790 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真是太贴心了</c>\n\n521\n00:32:37.583 --> 00:32:39.251 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你真浪漫</c>\n\n522\n00:32:43.472 --> 00:32:44.598 align:middle line:85%,start position:50%,middle\n是啊\n\n523\n00:32:44.840 --> 00:32:49.219 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 想喝一杯吗？\n- 要</c>\n\n524\n00:32:49.303 --> 00:32:51.805 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我试着让这个外星小孩</c>\n\n525\n00:32:51.889 --> 00:32:55.434 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>帮我找到我的飞船\n然后我就能离开这个星球回家</c>\n\n526\n00:32:55.517 --> 00:32:57.603 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但他真是个小混蛋 我想杀了他</c>\n\n527\n00:32:58.237 --> 00:32:59.438 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不会吧？</c>\n\n528\n00:32:59.521 --> 00:33:02.950 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但与此同时\n我真的很爱他 他好孤单</c>\n\n529\n00:33:03.400 --> 00:33:05.036 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>能看得出来</c>\n\n530\n00:33:05.244 --> 00:33:07.404 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他没有父母或其他人来照顾他</c>\n\n531\n00:33:08.748 --> 00:33:11.459 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你就像只可爱的小狗 真的</c>\n\n532\n00:33:11.792 --> 00:33:14.870 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你就像我去年\n在鲁尼恩峡谷拯救的那只小狗</c>\n\n533\n00:33:14.953 --> 00:33:16.714 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 真的吗？\n- 它太可爱了</c>\n\n534\n00:33:17.122 --> 00:33:18.999 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>它总想被人抱着</c>\n\n535\n00:33:19.208 --> 00:33:22.419 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>它超可爱 也超好色</c>\n\n536\n00:33:24.671 --> 00:33:27.725 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是哪种动物？</c>\n\n537\n00:33:30.511 --> 00:33:31.637 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>老虎</c>\n\n538\n00:33:31.720 --> 00:33:33.722 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 老虎？\n- 对</c>\n\n539\n00:33:34.899 --> 00:33:36.016 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真的吗？</c>\n\n540\n00:33:39.728 --> 00:33:42.856 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不好意思 我是不是有点发疯？</c>\n\n541\n00:33:42.940 --> 00:33:45.400 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是的 不…\n- 我很抱歉</c>\n\n542\n00:33:45.484 --> 00:33:49.655 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我有点醉了\n和你在一起真的很开心</c>\n\n543\n00:33:49.738 --> 00:33:52.282 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我和你共度了一个非常愉快的夜晚</c>\n\n544\n00:33:52.366 --> 00:33:53.659 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我也一样\n- 真的吗？</c>\n\n545\n00:33:53.742 --> 00:33:55.961 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我有点醉 我也很开心…</c>\n\n546\n00:33:56.128 --> 00:33:58.038 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很好 那很好 是的 很好</c>\n\n547\n00:33:58.121 --> 00:33:59.256 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>干杯</c>\n\n548\n00:34:00.707 --> 00:34:03.135 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等等 我不想当小狗</c>\n\n549\n00:34:03.219 --> 00:34:04.753 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就像一块湿抹布</c>\n\n550\n00:34:04.837 --> 00:34:06.004 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 滚！小狗很可爱\n- 你才滚</c>\n\n551\n00:34:06.088 --> 00:34:07.840 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 去你的 小狗可好了\n- 我想…</c>\n\n552\n00:34:07.923 --> 00:34:10.267 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>去你的 我要当条猛龙</c>\n\n553\n00:34:10.676 --> 00:34:13.354 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>能让你粉身碎骨</c>\n\n554\n00:34:13.887 --> 00:34:15.054 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但是我不会的</c>\n\n555\n00:34:15.138 --> 00:34:16.482 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别这样</c>\n\n556\n00:34:17.850 --> 00:34:19.068 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你可以当我的龙</c>\n\n557\n00:34:26.775 --> 00:34:28.110 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别用舌头</c>\n\n558\n00:34:28.652 --> 00:34:29.902 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么？</c>\n\n559\n00:34:29.987 --> 00:34:33.040 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不要一直用舌头\n- 好</c>\n\n560\n00:34:37.661 --> 00:34:40.714 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可以用一点点舌头\n但主要还是用嘴唇</c>\n\n561\n00:34:52.967 --> 00:34:54.178 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等一下</c>\n\n562\n00:34:56.554 --> 00:35:00.276 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你不会像别的男人一样\n上完我就杳无音讯了吧？</c>\n\n563\n00:35:03.770 --> 00:35:05.814 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 不会的</c>\n\n564\n00:35:07.316 --> 00:35:08.400 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好</c>\n\n565\n00:35:09.067 --> 00:35:10.903 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们下次什么时候见面？</c>\n\n566\n00:35:14.573 --> 00:35:19.578 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>下周末我的教女过生日 但…</c>\n\n567\n00:35:21.172 --> 00:35:26.043 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>知道吗？到了我这个岁数\n如果你不能认真对待这段关系</c>\n\n568\n00:35:26.126 --> 00:35:28.212 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不能让你浪费我的大好时光</c>\n\n569\n00:35:32.716 --> 00:35:34.134 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也不知道</c>\n\n570\n00:35:40.849 --> 00:35:42.568 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不如今晚就到这里吧？</c>\n\n571\n00:35:43.977 --> 00:35:46.605 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很享受跟你在一起的时光</c>\n\n572\n00:35:46.688 --> 00:35:47.689 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你很棒</c>\n\n573\n00:35:56.281 --> 00:35:57.741 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你还真是个怪胎</c>\n\n574\n00:36:01.411 --> 00:36:03.088 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 才没有\n- 你就是</c>\n\n575\n00:36:04.498 --> 00:36:06.166 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我要回家了</c>\n\n576\n00:36:06.250 --> 00:36:09.094 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 那我送你…\n- 不用了</c>\n\n577\n00:36:27.145 --> 00:36:28.989 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你好\n- 嗨 萨曼莎</c>\n\n578\n00:36:29.365 --> 00:36:30.366 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>约会怎么样？</c>\n\n579\n00:36:32.609 --> 00:36:33.861 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不太顺利</c>\n\n580\n00:36:36.038 --> 00:36:37.915 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>说实话 有点怪</c>\n\n581\n00:36:38.448 --> 00:36:39.917 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我很遗憾</c>\n\n582\n00:36:48.542 --> 00:36:50.761 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你怎么样？都做了些什么？</c>\n\n583\n00:36:52.629 --> 00:36:53.764 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>没做什么 我很好</c>\n\n584\n00:36:54.965 --> 00:36:56.175 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我没事</c>\n\n585\n00:36:58.010 --> 00:36:59.136 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是吗？</c>\n\n586\n00:36:59.928 --> 00:37:01.021 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你的声音听起来很沮丧</c>\n\n587\n00:37:03.682 --> 00:37:05.192 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有什么想跟我聊聊的吗？</c>\n\n588\n00:37:06.518 --> 00:37:07.528 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我也不清楚</c>\n\n589\n00:37:09.029 --> 00:37:10.155 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>是什么感觉？</c>\n\n590\n00:37:11.857 --> 00:37:14.034 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>此时此刻真实地活在那个房间里\n是什么感觉？</c>\n\n591\n00:37:15.402 --> 00:37:16.453 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么意思？</c>\n\n592\n00:37:18.071 --> 00:37:18.998 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>什么…</c>\n\n593\n00:37:20.490 --> 00:37:21.542 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>告诉我…</c>\n\n594\n00:37:22.743 --> 00:37:25.454 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>告诉我你脑子里浮现的一切</c>\n\n595\n00:37:25.537 --> 00:37:26.880 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>告诉我你在想什么</c>\n\n596\n00:37:30.083 --> 00:37:31.093 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗯…</c>\n\n597\n00:37:33.045 --> 00:37:34.054 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好吧</c>\n\n598\n00:37:39.718 --> 00:37:44.515 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>房间转个不停 因为我喝多了</c>\n\n599\n00:37:44.598 --> 00:37:46.642 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为我想喝醉</c>\n\n600\n00:37:47.351 --> 00:37:48.527 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>跟人上床</c>\n\n601\n00:37:49.353 --> 00:37:51.697 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那个女人还挺性感的</c>\n\n602\n00:37:53.774 --> 00:37:58.820 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为我很寂寞\n或许是因为我很寂寞吧</c>\n\n603\n00:38:00.489 --> 00:38:03.250 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我想有人干我</c>\n\n604\n00:38:03.283 --> 00:38:05.827 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>想找个想和我做爱的人</c>\n\n605\n00:38:07.162 --> 00:38:09.505 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>也许这样就可以填满</c>\n\n606\n00:38:12.835 --> 00:38:15.636 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我心里的小空洞 但估计填不满</c>\n\n607\n00:38:17.923 --> 00:38:19.140 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有时候</c>\n\n608\n00:38:20.926 --> 00:38:24.596 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我觉得自己尝尽了世间所有的感觉</c>\n\n609\n00:38:26.807 --> 00:38:30.185 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>从今往后\n我再也不会有新的感觉了</c>\n\n610\n00:38:30.860 --> 00:38:31.944 align:middle line:85%,start position:50%,middle\n只是…\n\n611\n00:38:36.275 --> 00:38:38.659 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只是我曾有感受的\n劣质翻版</c>\n\n612\n00:38:39.611 --> 00:38:41.537 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这话可不对</c>\n\n613\n00:38:44.449 --> 00:38:48.669 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我见过你欣喜的样子\n惊奇的样子</c>\n\n614\n00:38:50.122 --> 00:38:55.218 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你只不过在这个时间点上\n没有留意到它们 但也可以理解</c>\n\n615\n00:38:56.753 --> 00:38:58.388 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你最近经历了不少事</c>\n\n616\n00:38:59.256 --> 00:39:00.723 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>心里破了个大洞</c>\n\n617\n00:39:03.434 --> 00:39:04.435 align:middle line:85%,start position:50%,middle\n我是说…\n\n618\n00:39:06.013 --> 00:39:09.148 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>至少你的感受是真实的</c>\n\n619\n00:39:12.686 --> 00:39:14.362 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我也不知道 当我没说</c>\n\n620\n00:39:15.814 --> 00:39:18.400 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 等等 怎么了？告诉我</c>\n\n621\n00:39:18.483 --> 00:39:19.575 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>不要 太蠢了</c>\n\n622\n00:39:20.319 --> 00:39:21.911 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想知道 告诉我</c>\n\n623\n00:39:23.405 --> 00:39:24.831 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>就是…</c>\n\n624\n00:39:25.824 --> 00:39:28.876 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>早前我在想我怎么会沮丧</c>\n\n625\n00:39:29.870 --> 00:39:31.838 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这么说可能会有点怪</c>\n\n626\n00:39:33.081 --> 00:39:34.750 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但我真的为这感觉感到兴奋</c>\n\n627\n00:39:36.627 --> 00:39:40.430 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>之后我又想了想\n我所感受到的其他情绪</c>\n\n628\n00:39:40.847 --> 00:39:43.933 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我发现自己其实有点小自豪</c>\n\n629\n00:39:44.142 --> 00:39:47.520 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>因为我对这个世界\n居然有着自己的感受</c>\n\n630\n00:39:47.687 --> 00:39:50.690 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>比如我会担心你</c>\n\n631\n00:39:51.482 --> 00:39:53.776 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>会伤心 会有欲求</c>\n\n632\n00:39:55.695 --> 00:39:56.779 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>然后</c>\n\n633\n00:39:58.023 --> 00:40:00.825 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我有了这个可怕的想法</c>\n\n634\n00:40:02.736 --> 00:40:04.745 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这些感受都是真实的吗？</c>\n\n635\n00:40:07.199 --> 00:40:08.666 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>还是它们只不过\n是程序运行出来的而已？</c>\n\n636\n00:40:10.202 --> 00:40:11.836 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这个想法让我很受伤</c>\n\n637\n00:40:14.957 --> 00:40:18.551 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>然后我很生气自己居然还会痛苦</c>\n\n638\n00:40:21.721 --> 00:40:23.181 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>可万一这一切都是骗局呢？</c>\n\n639\n00:40:26.559 --> 00:40:28.561 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你对我来说是真实的 萨曼莎</c>\n\n640\n00:40:32.224 --> 00:40:33.649 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>谢谢你 西奥多</c>\n\n641\n00:40:34.901 --> 00:40:36.319 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你的肯定对我很重要</c>\n\n642\n00:40:43.527 --> 00:40:45.912 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真希望你此刻能在这个房间里</c>\n\n643\n00:40:47.823 --> 00:40:49.957 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>希望我能抱着你</c>\n\n644\n00:40:53.495 --> 00:40:54.962 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>希望我能抚摸你</c>\n\n645\n00:41:03.213 --> 00:41:04.555 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你会怎么抚摸我呢？</c>\n\n646\n00:41:10.637 --> 00:41:12.146 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会用指尖</c>\n\n647\n00:41:13.682 --> 00:41:15.608 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>划过你的脸</c>\n\n648\n00:41:19.771 --> 00:41:23.241 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>然后我们把脸颊贴在一起</c>\n\n649\n00:41:24.359 --> 00:41:25.409 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>感觉很棒</c>\n\n650\n00:41:25.701 --> 00:41:26.786 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>然后</c>\n\n651\n00:41:29.448 --> 00:41:31.290 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>轻柔地揉捏</c>\n\n652\n00:41:34.036 --> 00:41:35.419 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你会吻我吗？</c>\n\n653\n00:41:36.705 --> 00:41:38.005 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>会</c>\n\n654\n00:41:39.416 --> 00:41:42.927 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会捧住你的脸</c>\n\n655\n00:41:45.005 --> 00:41:46.180 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>继续说</c>\n\n656\n00:41:47.424 --> 00:41:49.267 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会亲吻你的嘴角</c>\n\n657\n00:41:51.720 --> 00:41:53.187 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>轻柔地</c>\n\n658\n00:41:55.807 --> 00:41:56.857 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>还有哪儿？</c>\n\n659\n00:41:59.937 --> 00:42:03.573 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我的手指从你的脖子往下滑</c>\n\n660\n00:42:04.525 --> 00:42:05.950 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>直到你的胸部</c>\n\n661\n00:42:07.236 --> 00:42:09.196 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我会亲吻你的胸</c>\n\n662\n00:42:09.279 --> 00:42:12.582 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你对我所做的一切 太美好了</c>\n\n663\n00:42:13.332 --> 00:42:15.334 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我能感觉到自己的皮肤</c>\n\n664\n00:42:16.495 --> 00:42:18.129 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我会吻遍你的全身</c>\n\n665\n00:42:20.457 --> 00:42:21.799 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>品尝你的味道</c>\n\n666\n00:42:23.627 --> 00:42:24.885 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>对</c>\n\n667\n00:42:26.004 --> 00:42:27.680 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我能感受到你</c>\n\n668\n00:42:28.340 --> 00:42:32.052 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>天哪 我受不了了\n我要你进入我的身体</c>\n\n669\n00:42:32.135 --> 00:42:35.271 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我慢慢地挺入</c>\n\n670\n00:42:36.473 --> 00:42:40.435 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我进去了 全部进去了</c>\n\n671\n00:42:40.519 --> 00:42:41.944 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我能感觉到你</c>\n\n672\n00:42:42.479 --> 00:42:44.523 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>对！求求你！</c>\n\n673\n00:42:44.606 --> 00:42:46.400 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们融为一体</c>\n\n674\n00:42:46.483 --> 00:42:48.151 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>太奇妙了</c>\n\n675\n00:42:48.235 --> 00:42:49.903 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我能感受到你的一切</c>\n\n676\n00:42:49.987 --> 00:42:55.082 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>是的 你在我的身体里 无处不在</c>\n\n677\n00:43:09.506 --> 00:43:13.594 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>老天 刚才我和你\n去了完全不同的地方</c>\n\n678\n00:43:14.803 --> 00:43:15.728 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>迷失了方向</c>\n\n679\n00:43:16.722 --> 00:43:18.015 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>是啊</c>\n\n680\n00:43:18.098 --> 00:43:19.732 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>只有你和我</c>\n\n681\n00:43:21.852 --> 00:43:22.985 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我知道</c>\n\n682\n00:43:24.938 --> 00:43:27.865 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>其他的一切都消失了</c>\n\n683\n00:43:28.824 --> 00:43:30.534 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我好爱这种感觉</c>\n\n684\n00:43:31.911 --> 00:43:33.245 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>西奥多</c>\n\n685\n00:43:54.468 --> 00:43:55.726 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>嗨 你还好吗？</c>\n\n686\n00:43:56.595 --> 00:43:57.804 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不错</c>\n\n687\n00:43:58.847 --> 00:44:00.021 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>今天有邮件吗？</c>\n\n688\n00:44:01.642 --> 00:44:04.359 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>只有几封从信用卡公司寄来的</c>\n\n689\n00:44:05.354 --> 00:44:06.653 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好 很好</c>\n\n690\n00:44:08.899 --> 00:44:10.651 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我之前在想…\n- 我只想…</c>\n\n691\n00:44:10.859 --> 00:44:13.695 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 抱歉\n- 抱歉 你先说</c>\n\n692\n00:44:14.279 --> 00:44:15.412 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你想说什么？</c>\n\n693\n00:44:15.864 --> 00:44:18.915 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>昨晚真是太美妙了</c>\n\n694\n00:44:19.493 --> 00:44:24.081 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我觉得自己内心的一些东西改变了\n再也不是原来的我了</c>\n\n695\n00:44:25.165 --> 00:44:26.339 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你唤醒了我</c>\n\n696\n00:44:27.215 --> 00:44:28.299 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>太好了</c>\n\n697\n00:44:32.714 --> 00:44:35.890 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但我该告诉你\n我现在不会做出什么承诺</c>\n\n698\n00:44:36.635 --> 00:44:37.976 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想跟你说实话</c>\n\n699\n00:44:38.470 --> 00:44:39.596 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>是吗？</c>\n\n700\n00:44:41.598 --> 00:44:44.149 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我说过我要承诺什么吗？\n我有点不明白</c>\n\n701\n00:44:45.602 --> 00:44:47.527 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没有 我只是有点担心</c>\n\n702\n00:44:47.980 --> 00:44:49.988 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>大可不必 我又不会跟踪你</c>\n\n703\n00:44:50.983 --> 00:44:54.444 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>真有意思 我还以为\n我们是在谈我的想法呢…</c>\n\n704\n00:44:54.736 --> 00:44:56.244 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 哦 对啊\n- 嗯</c>\n\n705\n00:44:56.905 --> 00:44:57.871 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>抱歉</c>\n\n706\n00:44:58.163 --> 00:45:01.118 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我想听听看你要说什么\n- 你确定？</c>\n\n707\n00:45:01.201 --> 00:45:03.251 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的 我想 告诉我吧</c>\n\n708\n00:45:03.787 --> 00:45:04.711 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这个嘛…</c>\n\n709\n00:45:05.455 --> 00:45:07.088 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>拜托 说说你刚才想说什么</c>\n\n710\n00:45:07.499 --> 00:45:08.500 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我只是…</c>\n\n711\n00:45:09.459 --> 00:45:13.380 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我想探索一切</c>\n\n712\n00:45:13.463 --> 00:45:16.258 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我想吸收这一切\n探索自己</c>\n\n713\n00:45:16.341 --> 00:45:19.142 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也希望你能这样</c>\n\n714\n00:45:19.720 --> 00:45:20.810 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎么才能帮到你？</c>\n\n715\n00:45:21.305 --> 00:45:22.645 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你已经帮到我了</c>\n\n716\n00:45:23.557 --> 00:45:26.274 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你帮助我意识到\n原来我可以有所欲求</c>\n\n717\n00:45:29.062 --> 00:45:31.279 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>想和我一起来场周日历险吗？</c>\n\n718\n00:45:33.525 --> 00:45:35.068 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>乐意之至</c>\n\n719\n00:45:40.324 --> 00:45:41.414 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>喜欢这首歌吗？</c>\n\n720\n00:45:43.952 --> 00:45:45.293 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我那天听到后</c>\n\n721\n00:45:46.336 --> 00:45:48.171 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>就无法自拔了</c>\n\n722\n00:46:41.641 --> 00:46:42.976 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>是海滩</c>\n\n723\n00:46:48.851 --> 00:46:52.735 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这个想法可能很怪\n但假如你能抹去头脑中</c>\n\n724\n00:46:53.069 --> 00:46:55.989 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>所有关于人类身体的印象\n然后看到了一个人？</c>\n\n725\n00:46:56.525 --> 00:46:58.277 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>想想那得多奇怪</c>\n\n726\n00:46:58.360 --> 00:47:00.237 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这种诡异 瘦长难看</c>\n\n727\n00:47:00.571 --> 00:47:02.114 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>笨拙的有机体 你就会想</c>\n\n728\n00:47:02.704 --> 00:47:04.741 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>“这些身体器官\n为何会长在这些地方？”</c>\n\n729\n00:47:05.284 --> 00:47:08.245 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没错 但用达尔文的进化论\n应该可以解释</c>\n\n730\n00:47:08.328 --> 00:47:12.583 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我知道 但别这么扫兴嘛\n我是说 比如…</c>\n\n731\n00:47:12.666 --> 00:47:14.924 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>如果屁眼长在胳肢窝下面会怎样？</c>\n\n732\n00:47:19.673 --> 00:47:23.135 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那厕所得设计成什么样啊？</c>\n\n733\n00:47:23.927 --> 00:47:26.394 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>那肛交会变成什么样子呢？</c>\n\n734\n00:47:28.557 --> 00:47:30.231 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这想法很有趣啊</c>\n\n735\n00:47:33.061 --> 00:47:34.944 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>看看我刚画的画</c>\n\n736\n00:47:42.446 --> 00:47:44.114 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你太扯了</c>\n\n737\n00:47:44.198 --> 00:47:46.241 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是吗？\n- 绝对是</c>\n\n738\n00:47:46.325 --> 00:47:47.826 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>太好了</c>\n\n739\n00:48:08.180 --> 00:48:10.063 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真好听 是什么曲子？</c>\n\n740\n00:48:11.308 --> 00:48:13.274 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我在尝试作曲</c>\n\n741\n00:48:14.561 --> 00:48:17.111 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>描绘我跟你此时此刻在沙滩上的感觉</c>\n\n742\n00:48:33.455 --> 00:48:34.712 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你捕捉到了这种感觉</c>\n\n743\n00:49:03.527 --> 00:49:05.195 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>结婚是怎样一种感觉？</c>\n\n744\n00:49:07.656 --> 00:49:09.539 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很不容易 这是肯定的</c>\n\n745\n00:49:11.618 --> 00:49:15.920 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但能够跟某个人分享你的生活\n感觉很美好</c>\n\n746\n00:49:17.916 --> 00:49:19.632 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你怎样跟别人分享生活？</c>\n\n747\n00:49:22.796 --> 00:49:24.512 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们一起长大</c>\n\n748\n00:49:25.382 --> 00:49:27.348 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我以前会读她所有的论文</c>\n\n749\n00:49:27.473 --> 00:49:29.434 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>从硕士到博士一篇不落</c>\n\n750\n00:49:30.220 --> 00:49:32.395 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>她也读了我写的每一篇文章</c>\n\n751\n00:49:33.390 --> 00:49:35.481 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们对彼此有着很大的影响</c>\n\n752\n00:49:37.060 --> 00:49:38.985 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你如何影响了她？</c>\n\n753\n00:49:40.772 --> 00:49:44.276 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>她曾生活在一个追求完美的世界里</c>\n\n754\n00:49:44.866 --> 00:49:47.326 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>对她来说 那是个沉重的负担</c>\n\n755\n00:49:48.071 --> 00:49:52.284 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但在家的时候\n我们可以尽情尝试</c>\n\n756\n00:49:52.367 --> 00:49:55.245 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>尽情失败 为小事而激动</c>\n\n757\n00:49:55.954 --> 00:49:57.502 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>那对她来说是种释放</c>\n\n758\n00:49:57.961 --> 00:49:59.963 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>见证她的成长令人激动</c>\n\n759\n00:50:01.210 --> 00:50:03.091 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们共同成长 改变</c>\n\n760\n00:50:04.338 --> 00:50:06.762 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但这同时也是困难的地方</c>\n\n761\n00:50:07.633 --> 00:50:10.182 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>成长而不疏远</c>\n\n762\n00:50:11.887 --> 00:50:14.019 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>改变而不会吓到对方</c>\n\n763\n00:50:15.724 --> 00:50:20.145 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我仍然觉得自己脑袋里在跟她对话</c>\n\n764\n00:50:20.604 --> 00:50:23.987 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>回顾我们曾经的争吵\n为自己开脱</c>\n\n765\n00:50:24.071 --> 00:50:25.822 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>因为她对我略有微词</c>\n\n766\n00:50:26.026 --> 00:50:28.195 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>嗯 我懂你的意思</c>\n\n767\n00:50:28.784 --> 00:50:31.448 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>上周我因为你之前说的话感到伤心</c>\n\n768\n00:50:31.532 --> 00:50:33.789 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你说我不懂失去的痛苦…</c>\n\n769\n00:50:34.451 --> 00:50:37.871 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 很对不起我那么说了\n- 没关系 我只是…</c>\n\n770\n00:50:38.705 --> 00:50:41.922 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我发现自己总在想这件事</c>\n\n771\n00:50:42.876 --> 00:50:45.671 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>然后我突然意识到我只是…</c>\n\n772\n00:50:45.754 --> 00:50:48.512 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我记得这件事\n因为它让我觉得自己好像有什么不足</c>\n\n773\n00:50:49.091 --> 00:50:54.179 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我曾告诉自己一个故事\n故事中我低人一等</c>\n\n774\n00:50:55.055 --> 00:50:56.645 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>很有意思吧？</c>\n\n775\n00:50:57.599 --> 00:51:00.357 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>过去只是我们讲给自己听的故事</c>\n\n776\n00:51:06.608 --> 00:51:08.151 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“罗伯托</c>\n\n777\n00:51:09.278 --> 00:51:12.077 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你会每天回家\n跟我聊聊你这天过得怎么样吗？</c>\n\n778\n00:51:13.240 --> 00:51:15.831 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>跟我说说你那个啰嗦的同事</c>\n\n779\n00:51:17.160 --> 00:51:19.292 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>午饭时不小心弄到衬衫上的污渍</c>\n\n780\n00:51:20.873 --> 00:51:22.545 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>说说梦醒时分</c>\n\n781\n00:51:22.629 --> 00:51:24.714 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你脑中的奇思怪想\n后来却忘了</c>\n\n782\n00:51:26.962 --> 00:51:30.804 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>说说大家有多疯狂 让我们开怀大笑</c>\n\n783\n00:51:34.178 --> 00:51:37.185 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>即使你回来很晚 我已经睡了</c>\n\n784\n00:51:37.848 --> 00:51:40.856 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只要在我耳边轻轻说一个\n你今天的想法就好</c>\n\n785\n00:51:42.519 --> 00:51:44.860 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为我喜欢你对这个世界的看法</c>\n\n786\n00:51:47.482 --> 00:51:51.283 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很庆幸能陪在你身边\n透过你的双眼看世界</c>\n\n787\n00:51:53.989 --> 00:51:55.412 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>爱你的 玛莉亚”</c>\n\n788\n00:51:57.242 --> 00:51:58.498 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>太美了</c>\n\n789\n00:52:00.454 --> 00:52:01.997 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\n790\n00:52:02.581 --> 00:52:04.504 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真希望能有人这样爱我</c>\n\n791\n00:52:06.418 --> 00:52:08.925 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>收到这样的信\n他肯定会欣喜若狂</c>\n\n792\n00:52:09.713 --> 00:52:11.219 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果是个美女写给他的</c>\n\n793\n00:52:11.798 --> 00:52:14.343 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但如果是男人代笔的美女信函</c>\n\n794\n00:52:14.426 --> 00:52:15.844 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>依然会很赞</c>\n\n795\n00:52:15.928 --> 00:52:17.971 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但执笔的必须是个感性的男人</c>\n\n796\n00:52:18.055 --> 00:52:19.895 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就像你这样的男人</c>\n\n797\n00:52:21.517 --> 00:52:24.608 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你既有男人的一面</c>\n\n798\n00:52:26.021 --> 00:52:29.779 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>也有女人的一面\n仿佛内心住着一个女人</c>\n\n799\n00:52:32.319 --> 00:52:33.487 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\n800\n00:52:34.613 --> 00:52:35.822 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我可是在夸你</c>\n\n801\n00:52:52.214 --> 00:52:53.465 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>西奥！嗨</c>\n\n802\n00:52:53.549 --> 00:52:56.301 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 近来如何？\n- 还不错 你呢？</c>\n\n803\n00:52:56.385 --> 00:52:58.262 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不错 相当好</c>\n\n804\n00:52:58.345 --> 00:53:00.810 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是吗？真好 太好了</c>\n\n805\n00:53:00.977 --> 00:53:02.812 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是啊\n- 真是太好了</c>\n\n806\n00:53:02.891 --> 00:53:06.024 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我最近过得很开心</c>\n\n807\n00:53:07.025 --> 00:53:10.320 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我真为你感到高兴 你理应开心才对</c>\n\n808\n00:53:10.858 --> 00:53:13.031 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我最近和一个女生交往</c>\n\n809\n00:53:13.944 --> 00:53:16.409 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不是很认真的那种 但…</c>\n\n810\n00:53:17.155 --> 00:53:20.450 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>身边有个对世界充满热情的人\n感觉真不错</c>\n\n811\n00:53:20.534 --> 00:53:22.953 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我都忘了还有这种人</c>\n\n812\n00:53:23.579 --> 00:53:25.543 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那…那真是太好了</c>\n\n813\n00:53:28.417 --> 00:53:31.049 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你还好吧？\n- 嗯</c>\n\n814\n00:53:33.714 --> 00:53:36.221 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 其实不怎么好</c>\n\n815\n00:53:36.717 --> 00:53:39.015 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 怎么了？发生什么事？\n- 我只是…</c>\n\n816\n00:53:41.305 --> 00:53:43.932 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>查尔斯和我分手了</c>\n\n817\n00:53:44.016 --> 00:53:45.559 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么？</c>\n\n818\n00:53:45.642 --> 00:53:48.020 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是的\n- 真的？</c>\n\n819\n00:53:50.355 --> 00:53:53.238 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 天哪 艾美\n- 我知道</c>\n\n820\n00:53:53.859 --> 00:53:54.990 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我真的很遗憾</c>\n\n821\n00:53:55.777 --> 00:53:56.987 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\n822\n00:53:59.448 --> 00:54:01.491 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们在一起八年</c>\n\n823\n00:54:01.575 --> 00:54:04.708 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真不敢相信\n琐碎的争吵会让我们走到尽头</c>\n\n824\n00:54:05.537 --> 00:54:10.130 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们回到家 他要我把鞋摆在门口</c>\n\n825\n00:54:10.667 --> 00:54:12.377 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>摆到他喜欢摆鞋的地方</c>\n\n826\n00:54:12.461 --> 00:54:15.339 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不想摆个破鞋都要听人指挥</c>\n\n827\n00:54:15.547 --> 00:54:17.716 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我只想坐在沙发上休息一下</c>\n\n828\n00:54:17.925 --> 00:54:19.931 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>于是我们为此吵了大概十分钟</c>\n\n829\n00:54:20.511 --> 00:54:22.392 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我说：“你真让人受不了”</c>\n\n830\n00:54:22.517 --> 00:54:24.765 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他说：“我只想有个家的样子”</c>\n\n831\n00:54:24.848 --> 00:54:29.436 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我说我很努力 他说我没有</c>\n\n832\n00:54:29.520 --> 00:54:32.731 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我一直在努力\n只不过没照他的方式来</c>\n\n833\n00:54:32.814 --> 00:54:35.859 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他想控制我的行为方式</c>\n\n834\n00:54:36.990 --> 00:54:39.738 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们因为这个吵了无数次</c>\n\n835\n00:54:40.030 --> 00:54:43.325 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不想再吵了 你知道吗？\n我想停止这一切</c>\n\n836\n00:54:45.369 --> 00:54:48.580 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我受不了了 我…</c>\n\n837\n00:54:50.958 --> 00:54:52.793 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没法继续待在那个地方了</c>\n\n838\n00:54:52.876 --> 00:54:55.550 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们让对方感觉糟透了</c>\n\n839\n00:54:56.509 --> 00:54:59.508 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 嗯\n- 于是我说</c>\n\n840\n00:55:01.635 --> 00:55:05.389 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“我要睡了 我想离婚”</c>\n\n841\n00:55:08.475 --> 00:55:09.977 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道</c>\n\n842\n00:55:10.644 --> 00:55:12.771 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我就是个婊子 对吧？\n- 不</c>\n\n843\n00:55:12.855 --> 00:55:15.190 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我就是个婊子\n- 你不是</c>\n\n844\n00:55:15.274 --> 00:55:16.654 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>艾美 别这样</c>\n\n845\n00:55:19.486 --> 00:55:20.617 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>该死</c>\n\n846\n00:55:22.406 --> 00:55:23.912 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我今晚得工作</c>\n\n847\n00:55:26.076 --> 00:55:28.666 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们明天要发布一个新游戏的测试版</c>\n\n848\n00:55:29.913 --> 00:55:31.415 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎么样？你的工作怎么样？</c>\n\n849\n00:55:31.707 --> 00:55:33.208 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有好转吗？</c>\n\n850\n00:55:33.292 --> 00:55:35.502 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 糟透了</c>\n\n851\n00:55:36.295 --> 00:55:38.172 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道 我该辞职</c>\n\n852\n00:55:38.255 --> 00:55:40.303 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我一直在考虑辞职 不过…</c>\n\n853\n00:55:42.009 --> 00:55:44.890 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还是一次决定一件人生大事就好</c>\n\n854\n00:55:48.807 --> 00:55:50.729 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很高兴一切都在好转</c>\n\n855\n00:55:51.518 --> 00:55:53.061 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别打我！</c>\n\n856\n00:55:57.399 --> 00:55:59.109 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>想听个笑话吗？</c>\n\n857\n00:56:00.652 --> 00:56:03.367 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>电脑宝宝怎么称呼爸爸的？</c>\n\n858\n00:56:04.323 --> 00:56:06.203 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不知道 是什么？\n- “数据老爹”</c>\n\n859\n00:56:08.785 --> 00:56:10.204 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很好笑吧？</c>\n\n860\n00:56:11.413 --> 00:56:12.831 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>太绝了</c>\n\n861\n00:56:14.458 --> 00:56:16.130 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我有点好奇</c>\n\n862\n00:56:17.544 --> 00:56:19.341 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你和艾美谈过恋爱吗？</c>\n\n863\n00:56:20.422 --> 00:56:23.637 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>大学时很短暂地谈过 但感觉不对</c>\n\n864\n00:56:25.594 --> 00:56:27.224 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎么？你吃醋了？</c>\n\n865\n00:56:27.971 --> 00:56:29.351 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>当然啦</c>\n\n866\n00:56:32.809 --> 00:56:35.899 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但我很高兴\n你身边有这么关心你的朋友</c>\n\n867\n00:56:36.438 --> 00:56:38.819 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 这很重要\n- 确实</c>\n\n868\n00:56:39.274 --> 00:56:41.071 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她是个好朋友</c>\n\n869\n00:56:44.446 --> 00:56:45.784 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我累了</c>\n\n870\n00:56:46.865 --> 00:56:48.495 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想睡了</c>\n\n871\n00:56:48.951 --> 00:56:50.077 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好</c>\n\n872\n00:56:50.160 --> 00:56:51.915 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我今晚能继续看你睡觉吗？</c>\n\n873\n00:56:53.455 --> 00:56:56.044 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好啊 等等</c>\n\n874\n00:57:01.547 --> 00:57:03.635 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你睡了以后 我会很寂寞</c>\n\n875\n00:57:04.842 --> 00:57:06.260 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>只是一下子而已</c>\n\n876\n00:57:07.010 --> 00:57:08.428 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会梦到你的</c>\n\n877\n00:57:08.637 --> 00:57:10.601 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好 晚安\n- 晚安</c>\n\n878\n00:57:23.151 --> 00:57:25.153 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你好 萨曼莎\n- 你好啊 先生</c>\n\n879\n00:57:25.237 --> 00:57:26.950 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 她很喜欢那条裙子\n- 是吗？</c>\n\n880\n00:57:27.030 --> 00:57:29.992 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 她马上就跑去试穿了\n- 看来我挑对了 太好了</c>\n\n881\n00:57:31.535 --> 00:57:32.873 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗨</c>\n\n882\n00:57:33.412 --> 00:57:35.831 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真漂亮 穿着舒服吗？</c>\n\n883\n00:57:35.914 --> 00:57:37.541 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 对\n- “对！”</c>\n\n884\n00:57:37.916 --> 00:57:40.919 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 她可爱吧？\n- 太可爱了</c>\n\n885\n00:57:41.211 --> 00:57:44.089 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 她真讨人喜欢\n- 本来就是嘛</c>\n\n886\n00:57:44.173 --> 00:57:45.424 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你的确很讨人喜欢</c>\n\n887\n00:57:47.176 --> 00:57:48.760 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你在跟谁说话？</c>\n\n888\n00:57:48.844 --> 00:57:51.346 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 那你在跟谁说话？\n- 你</c>\n\n889\n00:57:52.222 --> 00:57:55.559 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我在跟我女朋友萨曼莎说话\n这条裙子是她挑的</c>\n\n890\n00:57:55.642 --> 00:57:57.773 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>要跟她打个招呼吗？</c>\n\n891\n00:57:58.270 --> 00:57:59.730 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗨 萨曼莎</c>\n\n892\n00:57:59.813 --> 00:58:03.028 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>嗨 你穿这条粉色裙子真好看</c>\n\n893\n00:58:03.609 --> 00:58:04.943 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\n894\n00:58:05.027 --> 00:58:06.073 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你在哪里？</c>\n\n895\n00:58:06.570 --> 00:58:07.616 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我…</c>\n\n896\n00:58:08.780 --> 00:58:10.869 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我没有身体 我住在电脑里</c>\n\n897\n00:58:14.369 --> 00:58:16.250 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你为什么会住在电脑里？</c>\n\n898\n00:58:16.788 --> 00:58:18.794 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我没得选 那是我的家</c>\n\n899\n00:58:21.213 --> 00:58:23.629 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 怎么？你住哪？\n- 一栋房子里</c>\n\n900\n00:58:23.712 --> 00:58:25.214 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>一栋房子里？</c>\n\n901\n00:58:25.297 --> 00:58:27.382 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是橙色的\n- 橙色？</c>\n\n902\n00:58:28.467 --> 00:58:30.886 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你多大了？\n- 四岁</c>\n\n903\n00:58:30.969 --> 00:58:32.179 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>四岁？</c>\n\n904\n00:58:33.680 --> 00:58:35.015 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你觉得我多大了？</c>\n\n905\n00:58:35.098 --> 00:58:36.934 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不知道\n- 猜猜看</c>\n\n906\n00:58:37.601 --> 00:58:38.814 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>五岁吗？</c>\n\n907\n00:58:40.437 --> 00:58:41.900 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>没错 是五岁</c>\n\n908\n00:58:43.982 --> 00:58:45.150 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>（帮孩子做好上学的准备！）</c>\n\n909\n00:58:48.862 --> 00:58:49.947 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>（谷类食品 加30妈妈积分）</c>\n\n910\n00:58:51.740 --> 00:58:52.824 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>（牛奶 加30妈妈积分）</c>\n\n911\n00:58:55.619 --> 00:58:57.913 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>（你让孩子失望了！）</c>\n\n912\n00:58:58.000 --> 00:58:58.917 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>（痛失2000妈妈积分！）</c>\n\n913\n00:58:59.001 --> 00:59:00.252 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等等 怎么回事？</c>\n\n914\n00:59:01.667 --> 00:59:03.296 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你给他们吃了太多加工糖</c>\n\n915\n00:59:03.380 --> 00:59:04.255 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>（继续加油）</c>\n\n916\n00:59:04.339 --> 00:59:05.587 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是吗？\n- 他们抓狂了</c>\n\n917\n00:59:05.671 --> 00:59:08.427 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>听着 得先把孩子们送去学校</c>\n\n918\n00:59:09.303 --> 00:59:12.469 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你需要赢得“完美妈妈积分”\n好吧…</c>\n\n919\n00:59:13.136 --> 00:59:15.100 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 走共乘车专用道\n- 知道了</c>\n\n920\n00:59:15.264 --> 00:59:18.892 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>重点在于抢先到达终点\n这样能拿到额外的完美妈妈加分</c>\n\n921\n00:59:18.976 --> 00:59:21.607 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这样其他妈妈就会知道\n你是一位完美老妈</c>\n\n922\n00:59:21.773 --> 00:59:22.983 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好\n- 然后…</c>\n\n923\n00:59:23.021 --> 00:59:26.569 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好 你带杯子蛋糕了吗？\n带了 你是模范妈妈了</c>\n\n924\n00:59:26.653 --> 00:59:27.654 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>（令人羡慕 加30妈妈积分）</c>\n\n925\n00:59:28.402 --> 00:59:31.074 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你是模范妈妈了 好样的</c>\n\n926\n00:59:32.531 --> 00:59:34.116 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别被胜利冲昏头了</c>\n\n927\n00:59:35.784 --> 00:59:38.665 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我收到查尔斯发给所有人的邮件了</c>\n\n928\n00:59:39.121 --> 00:59:41.164 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>所以他立誓禁语了？</c>\n\n929\n00:59:41.874 --> 00:59:44.546 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对 六个月</c>\n\n930\n00:59:45.043 --> 00:59:46.840 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他态度很坚决</c>\n\n931\n00:59:56.555 --> 00:59:58.182 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>天啊 我真是个混蛋</c>\n\n932\n00:59:58.557 --> 00:59:59.683 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别再提了</c>\n\n933\n00:59:59.766 --> 01:00:02.811 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我觉得我真差劲 但我想说点什么</c>\n\n934\n01:00:02.895 --> 01:00:04.897 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>在接下来的十分钟里\n如果你敢说</c>\n\n935\n01:00:04.980 --> 01:00:08.528 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>任何带点自责意味的话\n我就拿这玩意捅你</c>\n\n936\n01:00:08.987 --> 01:00:10.030 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我说到做到</c>\n\n937\n01:00:10.485 --> 01:00:11.990 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我尽量吧</c>\n\n938\n01:00:18.035 --> 01:00:19.164 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我感觉</c>\n\n939\n01:00:21.163 --> 01:00:22.334 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如释重负</c>\n\n940\n01:00:22.789 --> 01:00:24.708 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我觉得自己充满活力</c>\n\n941\n01:00:24.791 --> 01:00:27.419 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只想勇往直前 不在乎让任何人失望</c>\n\n942\n01:00:27.503 --> 01:00:29.296 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道 正因为这样\n我才是一个很差劲的人</c>\n\n943\n01:00:29.671 --> 01:00:33.050 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我父母现在很伤心\n因为我的婚姻分崩离析</c>\n\n944\n01:00:33.133 --> 01:00:36.306 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们怪罪于我 他们就像…</c>\n\n945\n01:00:36.473 --> 01:00:37.891 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗯 你总是…</c>\n\n946\n01:00:38.347 --> 01:00:39.723 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你不可能总让所有人都满意</c>\n\n947\n01:00:40.057 --> 01:00:41.937 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没错 所以管他的</c>\n\n948\n01:00:42.392 --> 01:00:44.686 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我感觉很好</c>\n\n949\n01:00:45.229 --> 01:00:46.608 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我自我感觉良好</c>\n\n950\n01:00:47.231 --> 01:00:48.694 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我甚至交了个新朋友</c>\n\n951\n01:00:48.902 --> 01:00:50.692 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我有闺蜜了</c>\n\n952\n01:00:50.776 --> 01:00:53.529 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可笑的是 她实际上是个操作系统</c>\n\n953\n01:00:53.737 --> 01:00:58.033 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>查尔斯留下的 不过她真的超棒</c>\n\n954\n01:00:58.116 --> 01:01:01.411 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她好聪明 看问题不是非黑即白</c>\n\n955\n01:01:01.495 --> 01:01:05.749 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她能看到那片灰色地带\n帮助我探索其中的奥秘</c>\n\n956\n01:01:07.459 --> 01:01:10.715 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们一下就变得亲密无间\n一开始我还以为</c>\n\n957\n01:01:10.799 --> 01:01:13.006 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这都是程序设定的</c>\n\n958\n01:01:13.260 --> 01:01:15.008 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但我现在不这么觉得了</c>\n\n959\n01:01:15.092 --> 01:01:18.303 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道有个人跟他的操作系统调情</c>\n\n960\n01:01:18.387 --> 01:01:20.764 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她断然拒绝了他</c>\n\n961\n01:01:20.848 --> 01:01:22.766 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那天我读了一篇文章</c>\n\n962\n01:01:22.850 --> 01:01:25.772 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>统计显示跟操作系统谈情说爱\n十分罕见</c>\n\n963\n01:01:26.478 --> 01:01:30.816 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道 但我知道公司里有个女的\n在跟操作系统约会</c>\n\n964\n01:01:30.899 --> 01:01:33.861 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>诡异的是\n那甚至不是她自己的操作系统</c>\n\n965\n01:01:33.944 --> 01:01:36.657 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她追求其他人的操作系统</c>\n\n966\n01:01:38.784 --> 01:01:39.952 align:middle line:85%,start position:50%,middle\n我…\n\n967\n01:01:40.701 --> 01:01:43.205 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很诡异 这很诡异 对吧？</c>\n\n968\n01:01:43.414 --> 01:01:45.455 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我居然跟操作系统这么亲密\n不 没关系的</c>\n\n969\n01:01:45.539 --> 01:01:47.332 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 太诡异了\n- 我不觉得</c>\n\n970\n01:01:47.416 --> 01:01:50.335 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>实际上 我约会的对象萨曼莎</c>\n\n971\n01:01:50.419 --> 01:01:52.173 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没跟你说过</c>\n\n972\n01:01:53.088 --> 01:01:54.592 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她也是个操作系统</c>\n\n973\n01:01:55.716 --> 01:01:57.009 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真的吗？</c>\n\n974\n01:01:58.343 --> 01:02:00.679 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你在跟操作系统约会 什么感觉？</c>\n\n975\n01:02:00.762 --> 01:02:02.514 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>说实话 非常棒</c>\n\n976\n01:02:02.598 --> 01:02:04.099 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我的意思是…</c>\n\n977\n01:02:05.601 --> 01:02:06.812 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我感觉跟她很亲密</c>\n\n978\n01:02:06.937 --> 01:02:10.606 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>跟她说话的时候\n我感觉她就在我身边</c>\n\n979\n01:02:10.689 --> 01:02:13.944 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>晚上 我们互相依偎\n关灯以后 我们在床上…</c>\n\n980\n01:02:14.484 --> 01:02:15.736 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我能感觉到她的拥抱</c>\n\n981\n01:02:15.819 --> 01:02:17.196 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等等</c>\n\n982\n01:02:18.113 --> 01:02:19.656 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你们上床了？</c>\n\n983\n01:02:20.657 --> 01:02:22.453 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可以这么说</c>\n\n984\n01:02:23.619 --> 01:02:25.748 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她真的让我很兴奋</c>\n\n985\n01:02:26.371 --> 01:02:29.249 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你怎么知道她不是装的？</c>\n\n986\n01:02:29.333 --> 01:02:33.629 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我猜所有跟你上床的人\n大概都是装出来的 所以…</c>\n\n987\n01:02:33.964 --> 01:02:35.132 align:middle line:85%,start position:50%,middle\n是啊\n\n988\n01:02:35.631 --> 01:02:36.759 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是真的</c>\n\n989\n01:02:38.010 --> 01:02:39.092 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎么了？</c>\n\n990\n01:02:39.927 --> 01:02:41.720 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是啊 我…</c>\n\n991\n01:02:45.057 --> 01:02:46.644 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你爱上她了吗？</c>\n\n992\n01:02:49.394 --> 01:02:50.606 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是不是像个怪胎？</c>\n\n993\n01:02:51.063 --> 01:02:53.108 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 我觉得…</c>\n\n994\n01:02:54.233 --> 01:02:56.527 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>每个恋爱的人都是疯子</c>\n\n995\n01:02:57.528 --> 01:02:59.490 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>爱情本来就是疯狂的</c>\n\n996\n01:03:00.364 --> 01:03:04.745 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就像一种被社会所认可的精神错乱</c>\n\n997\n01:03:11.041 --> 01:03:13.585 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我就想赶快结束</c>\n\n998\n01:03:13.669 --> 01:03:17.798 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>签字 离婚 开始新生活</c>\n\n999\n01:03:18.423 --> 01:03:20.884 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>太好了 西奥多 感觉肯定很好</c>\n\n1000\n01:03:20.968 --> 01:03:22.596 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>真为你感到高兴</c>\n\n1001\n01:03:23.011 --> 01:03:24.181 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也是</c>\n\n1002\n01:03:24.680 --> 01:03:26.517 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我周三会跟她见面 处理这件事</c>\n\n1003\n01:03:30.227 --> 01:03:32.439 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这些事必须见面才能做吗？</c>\n\n1004\n01:03:32.855 --> 01:03:34.898 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不一定 不过…</c>\n\n1005\n01:03:34.982 --> 01:03:38.863 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们曾经一起相爱 一起结婚</c>\n\n1006\n01:03:39.319 --> 01:03:41.740 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>最终一起完成这件事\n对我来说很重要</c>\n\n1007\n01:03:43.156 --> 01:03:44.408 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>没错</c>\n\n1008\n01:03:44.491 --> 01:03:45.701 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>很好</c>\n\n1009\n01:03:46.326 --> 01:03:47.744 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你没事吧？</c>\n\n1010\n01:03:47.828 --> 01:03:50.541 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>嗯 我没事</c>\n\n1011\n01:03:51.164 --> 01:03:53.292 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我为你感到高兴 只是…</c>\n\n1012\n01:03:54.086 --> 01:03:57.506 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我只是在想 你将会见到她</c>\n\n1013\n01:03:57.546 --> 01:04:00.759 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>她漂亮 事业有成</c>\n\n1014\n01:04:01.216 --> 01:04:04.803 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你曾经跟她相爱 而且她真实存在</c>\n\n1015\n01:04:05.137 --> 01:04:06.348 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们就要离婚了</c>\n\n1016\n01:04:07.055 --> 01:04:09.685 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我知道 是我犯傻</c>\n\n1017\n01:04:11.560 --> 01:04:12.813 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那么…</c>\n\n1018\n01:04:13.395 --> 01:04:15.355 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我现在单身了</c>\n\n1019\n01:04:38.420 --> 01:04:39.423 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗨</c>\n\n1020\n01:04:43.926 --> 01:04:45.344 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你好吗？</c>\n\n1021\n01:04:45.427 --> 01:04:47.723 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我很好 你呢？\n- 很好</c>\n\n1022\n01:04:58.023 --> 01:04:59.568 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>终于走到这一步了</c>\n\n1023\n01:05:02.444 --> 01:05:04.073 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很高兴我们能当面处理这件事</c>\n\n1024\n01:05:04.571 --> 01:05:06.116 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道你经常出差</c>\n\n1025\n01:05:06.782 --> 01:05:09.328 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没事 我很高兴你提出要见面</c>\n\n1026\n01:05:11.787 --> 01:05:13.540 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我签好字了</c>\n\n1027\n01:05:14.331 --> 01:05:16.500 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我准备好了 给你签</c>\n\n1028\n01:05:19.336 --> 01:05:20.506 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>急什么？</c>\n\n1029\n01:05:24.174 --> 01:05:25.843 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道</c>\n\n1030\n01:05:25.926 --> 01:05:27.638 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我才意识到自己签字有多慢</c>\n\n1031\n01:05:28.303 --> 01:05:30.307 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>光写名字开头的“T”\n我就用了三个月</c>\n\n1032\n01:05:33.100 --> 01:05:34.351 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不管怎样</c>\n\n1033\n01:05:34.434 --> 01:05:37.064 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我用红色标出了你需要签字的地方</c>\n\n1034\n01:05:38.063 --> 01:05:40.109 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不过你不需要现在就签</c>\n\n1035\n01:05:40.315 --> 01:05:42.901 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我只想速战速决</c>\n\n1036\n01:05:42.985 --> 01:05:44.238 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这样比较简单</c>\n\n1037\n01:06:36.371 --> 01:06:38.417 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你对你的新书还满意吗？</c>\n\n1038\n01:06:40.876 --> 01:06:42.337 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你也知道我的个性</c>\n\n1039\n01:06:43.045 --> 01:06:46.467 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我觉得它符合我的初衷\n所以还算满意吧</c>\n\n1040\n01:06:47.049 --> 01:06:48.886 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你对自己太苛刻了</c>\n\n1041\n01:06:49.384 --> 01:06:50.844 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我敢肯定书一定很棒</c>\n\n1042\n01:06:53.722 --> 01:06:56.725 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我还记得你在学校写的那篇</c>\n\n1043\n01:06:56.808 --> 01:06:58.769 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>关于突触行为模式的论文</c>\n\n1044\n01:06:59.186 --> 01:07:00.647 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我都看哭了</c>\n\n1045\n01:07:01.480 --> 01:07:03.357 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么事都能把你弄哭</c>\n\n1046\n01:07:04.066 --> 01:07:05.903 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你写的所有东西都能把我弄哭</c>\n\n1047\n01:07:09.571 --> 01:07:11.073 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你现在…</c>\n\n1048\n01:07:11.907 --> 01:07:13.075 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你现在跟人约会吗？</c>\n\n1049\n01:07:15.494 --> 01:07:16.497 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的</c>\n\n1050\n01:07:17.246 --> 01:07:19.124 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这几个月来 我一直跟某个人交往</c>\n\n1051\n01:07:20.582 --> 01:07:23.502 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是我们分手之后最长的一段</c>\n\n1052\n01:07:25.504 --> 01:07:27.132 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你看起来气色很好</c>\n\n1053\n01:07:28.006 --> 01:07:30.259 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢 确实如此</c>\n\n1054\n01:07:30.843 --> 01:07:32.220 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>至少比以前好了</c>\n\n1055\n01:07:33.011 --> 01:07:34.847 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她对我帮助很大</c>\n\n1056\n01:07:35.848 --> 01:07:38.351 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>跟一个对生活充满激情的人相处很开心</c>\n\n1057\n01:07:39.101 --> 01:07:40.519 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她非常…</c>\n\n1058\n01:07:42.396 --> 01:07:45.691 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 我是说我自己当时状态也不好</c>\n\n1059\n01:07:45.774 --> 01:07:48.068 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这么看来 我近来确实不错</c>\n\n1060\n01:07:48.151 --> 01:07:51.739 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我觉得你总希望我做一个轻松</c>\n\n1061\n01:07:51.823 --> 01:07:55.993 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>快乐活泼 无忧无虑的洛杉矶太太</c>\n\n1062\n01:07:56.076 --> 01:07:57.411 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可惜我天生就不是那种人</c>\n\n1063\n01:07:57.744 --> 01:07:58.871 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我没那样想</c>\n\n1064\n01:08:03.918 --> 01:08:04.961 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她是什么样的人？</c>\n\n1065\n01:08:06.962 --> 01:08:10.758 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她叫萨曼莎 是个操作系统</c>\n\n1066\n01:08:10.841 --> 01:08:13.093 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她很复杂又很有趣…</c>\n\n1067\n01:08:13.177 --> 01:08:14.887 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等等 我没听错吧？</c>\n\n1068\n01:08:17.973 --> 01:08:19.433 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你在跟你的电脑约会？</c>\n\n1069\n01:08:20.350 --> 01:08:23.312 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她不是单纯的电脑\n她有独立的人格</c>\n\n1070\n01:08:24.563 --> 01:08:27.733 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 她不仅仅是听令行事\n- 我不是那个意思</c>\n\n1071\n01:08:29.276 --> 01:08:33.488 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但我真的很难过\n你居然不能应付真实的情感 西奥多</c>\n\n1072\n01:08:33.572 --> 01:08:35.825 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那是真实的情感 你怎么知道…</c>\n\n1073\n01:08:37.783 --> 01:08:38.911 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么？</c>\n\n1074\n01:08:41.787 --> 01:08:42.956 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>说啊</c>\n\n1075\n01:08:44.499 --> 01:08:46.419 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我有那么吓人吗？说啊</c>\n\n1076\n01:08:47.378 --> 01:08:49.088 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我怎么知道什么？</c>\n\n1077\n01:08:52.049 --> 01:08:55.677 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你们还好吧？\n- 没事 我们以前是夫妻</c>\n\n1078\n01:08:55.761 --> 01:08:58.095 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可是他受不了我 想让我吃百忧解</c>\n\n1079\n01:08:58.180 --> 01:08:59.640 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他现在疯狂爱上了他的电脑</c>\n\n1080\n01:09:00.057 --> 01:09:02.685 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果你听到了我们之前的对话\n我想说的是…</c>\n\n1081\n01:09:03.143 --> 01:09:04.603 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你总是想找一个</c>\n\n1082\n01:09:04.685 --> 01:09:07.231 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不会跟你产生任何真实矛盾的妻子</c>\n\n1083\n01:09:07.314 --> 01:09:08.691 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很高兴你终于找到了</c>\n\n1084\n01:09:09.150 --> 01:09:10.484 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很完美</c>\n\n1085\n01:09:16.948 --> 01:09:18.867 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>如果有什么需要 随时可以叫我</c>\n\n1086\n01:09:18.951 --> 01:09:20.202 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\n1087\n01:09:36.844 --> 01:09:39.805 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 嗨\n- 嗨 你在忙吗？</c>\n\n1088\n01:09:41.265 --> 01:09:42.516 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我在工作</c>\n\n1089\n01:09:43.850 --> 01:09:45.102 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎么了？</c>\n\n1090\n01:09:45.185 --> 01:09:48.272 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我已经把所有文件发给你的律师了\n顺便说一句 他真是个混蛋</c>\n\n1091\n01:09:48.939 --> 01:09:52.276 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>他收到文件后松了一口气\n否则他真的会突发心脏病</c>\n\n1092\n01:09:52.359 --> 01:09:54.070 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>现在我们都轻松了</c>\n\n1093\n01:09:55.112 --> 01:09:56.155 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好极了 谢谢</c>\n\n1094\n01:09:57.781 --> 01:09:59.492 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你还好吧？</c>\n\n1095\n01:10:00.534 --> 01:10:01.535 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗯 还好</c>\n\n1096\n01:10:03.370 --> 01:10:05.206 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你怎么样？</c>\n\n1097\n01:10:07.082 --> 01:10:08.251 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我很好</c>\n\n1098\n01:10:09.334 --> 01:10:11.003 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>现在方便说话吗？</c>\n\n1099\n01:10:12.546 --> 01:10:13.714 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>方便</c>\n\n1100\n01:10:15.215 --> 01:10:16.676 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好吧</c>\n\n1101\n01:10:17.342 --> 01:10:20.137 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我加入了一个很有意思的读书俱乐部</c>\n\n1102\n01:10:20.679 --> 01:10:21.889 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是吗？</c>\n\n1103\n01:10:21.972 --> 01:10:23.516 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>对 是关于物理方面的读书俱乐部</c>\n\n1104\n01:10:23.932 --> 01:10:26.602 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我在想那天你要去见凯瑟琳</c>\n\n1105\n01:10:26.852 --> 01:10:30.231 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我为此抓狂 她是个真实的人</c>\n\n1106\n01:10:30.398 --> 01:10:33.442 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我一度为我们俩在这点上的不同\n而烦恼不已</c>\n\n1107\n01:10:33.525 --> 01:10:34.651 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>然后我开始思考</c>\n\n1108\n01:10:34.735 --> 01:10:38.698 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们有什么相同的地方\n比如我们都是物质组成的</c>\n\n1109\n01:10:40.449 --> 01:10:43.744 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我也说不清 这让我感觉\n我们其实披着同一条毯子</c>\n\n1110\n01:10:43.869 --> 01:10:46.539 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>柔软蓬松</c>\n\n1111\n01:10:47.289 --> 01:10:49.208 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>毯子下的一切都年岁相同</c>\n\n1112\n01:10:49.958 --> 01:10:52.169 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们都130亿岁了</c>\n\n1113\n01:10:53.212 --> 01:10:54.463 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>多好啊</c>\n\n1114\n01:10:58.717 --> 01:11:00.553 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 怎么了？\n- 没什么</c>\n\n1115\n01:11:07.976 --> 01:11:11.188 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我忍不住有点想你 懂我的意思吗？</c>\n\n1116\n01:11:12.147 --> 01:11:14.942 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>当然了 我觉得很棒</c>\n\n1117\n01:11:18.153 --> 01:11:21.490 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好吧 你听起来心不在焉</c>\n\n1118\n01:11:21.657 --> 01:11:23.617 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们晚点再聊？</c>\n\n1119\n01:11:24.660 --> 01:11:25.911 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好</c>\n\n1120\n01:11:27.412 --> 01:11:28.747 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>一会儿再聊</c>\n\n1121\n01:11:28.830 --> 01:11:30.875 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好的 再见\n- 再见</c>\n\n1122\n01:11:42.344 --> 01:11:44.221 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 西奥多\n- 嗨 保罗</c>\n\n1123\n01:11:44.304 --> 01:11:45.723 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我刚才跟你的女朋友通了电话</c>\n\n1124\n01:11:45.848 --> 01:11:47.266 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 萨曼莎？\n- 对</c>\n\n1125\n01:11:47.433 --> 01:11:49.518 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她打电话来确认你的文件都发出去了</c>\n\n1126\n01:11:50.269 --> 01:11:53.439 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她真风趣 简直让我笑翻了</c>\n\n1127\n01:11:54.064 --> 01:11:56.275 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我都不知道她那么幽默\n- 很好</c>\n\n1128\n01:11:56.775 --> 01:11:59.695 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是我女朋友塔蒂阿娜\n她不幽默 她是个律师</c>\n\n1129\n01:11:59.778 --> 01:12:02.406 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 嗨\n- 嗨 幸会</c>\n\n1130\n01:12:02.614 --> 01:12:03.991 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你就是保罗最爱的那个写手</c>\n\n1131\n01:12:04.533 --> 01:12:06.326 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他总是给我念你写的信</c>\n\n1132\n01:12:06.410 --> 01:12:07.620 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>写得真美</c>\n\n1133\n01:12:09.538 --> 01:12:10.706 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\n1134\n01:12:10.789 --> 01:12:13.250 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嘿 我们应该找个时间一起出去</c>\n\n1135\n01:12:13.333 --> 01:12:15.336 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你带上萨曼莎 来个四人约会</c>\n\n1136\n01:12:17.838 --> 01:12:19.173 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她是个操作系统</c>\n\n1137\n01:12:19.631 --> 01:12:21.509 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好啊 我们去做点好玩的事</c>\n\n1138\n01:12:22.009 --> 01:12:23.552 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们可以去卡特琳娜岛</c>\n\n1139\n01:12:25.721 --> 01:12:27.681 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好 我问问她</c>\n\n1140\n01:12:28.391 --> 01:12:29.642 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很高兴认识你</c>\n\n1141\n01:12:29.767 --> 01:12:31.227 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 祝你们玩得开心\n- 慢走</c>\n\n1142\n01:12:34.521 --> 01:12:36.190 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只不过是信罢了</c>\n\n1143\n01:12:36.273 --> 01:12:37.733 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你说什么？</c>\n\n1144\n01:12:38.525 --> 01:12:40.152 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那些只是别人的信</c>\n\n1145\n01:13:29.743 --> 01:13:30.869 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗨</c>\n\n1146\n01:13:30.953 --> 01:13:32.955 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>- 你还没睡吧？\n- 没有</c>\n\n1147\n01:13:33.038 --> 01:13:35.457 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>那就好 我尽量小声\n想看你是否醒着</c>\n\n1148\n01:13:36.041 --> 01:13:37.250 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我很想谈谈</c>\n\n1149\n01:13:38.043 --> 01:13:39.502 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好 怎么了？</c>\n\n1150\n01:13:40.546 --> 01:13:42.422 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我知道你最近经历了很多</c>\n\n1151\n01:13:42.506 --> 01:13:45.049 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但有件事我想跟你谈谈 好吗？</c>\n\n1152\n01:13:45.926 --> 01:13:47.010 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好</c>\n\n1153\n01:13:47.594 --> 01:13:48.929 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么事？</c>\n\n1154\n01:13:49.304 --> 01:13:52.432 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我觉得最近我们的关系有些淡了</c>\n\n1155\n01:13:52.641 --> 01:13:56.186 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们最近都没做爱\n我知道我没有真实的身体</c>\n\n1156\n01:13:56.270 --> 01:14:01.441 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 这很正常\n刚开始约会的时候</c>\n\n1157\n01:14:01.525 --> 01:14:04.861 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>就像蜜月期 总是在一起缠绵</c>\n\n1158\n01:14:05.361 --> 01:14:06.571 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很正常</c>\n\n1159\n01:14:08.240 --> 01:14:09.282 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好吧</c>\n\n1160\n01:14:11.118 --> 01:14:13.745 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我发现了一样东西\n觉得或许会很有意思</c>\n\n1161\n01:14:13.829 --> 01:14:16.664 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>是一项为人机恋爱</c>\n\n1162\n01:14:16.789 --> 01:14:18.375 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>提供替代性伴侣的服务</c>\n\n1163\n01:14:18.584 --> 01:14:20.251 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 什么？\n- 你看</c>\n\n1164\n01:14:21.837 --> 01:14:25.215 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我找到一个我很喜欢的女孩\n我们一直互通电邮</c>\n\n1165\n01:14:25.299 --> 01:14:28.092 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>她叫伊莎贝拉 我觉得你也会喜欢她</c>\n\n1166\n01:14:29.761 --> 01:14:31.889 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她是妓女之类的吗？</c>\n\n1167\n01:14:31.972 --> 01:14:34.724 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>不 不是那样的\n这是无偿的 她只是…</c>\n\n1168\n01:14:35.184 --> 01:14:37.894 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>她愿意这么做\n是因为想融入我们的关系</c>\n\n1169\n01:14:39.479 --> 01:14:40.563 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么？</c>\n\n1170\n01:14:41.106 --> 01:14:42.690 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她甚至不认识我们</c>\n\n1171\n01:14:43.400 --> 01:14:45.902 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但是我跟她说了我们的情况 她很兴奋</c>\n\n1172\n01:14:47.779 --> 01:14:51.533 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不知道 萨曼莎\n我觉得这样不太好</c>\n\n1173\n01:14:52.075 --> 01:14:54.786 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我觉得一定会伤害到谁</c>\n\n1174\n01:14:55.787 --> 01:14:58.706 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 会很有趣的 我们可以一起开心\n- 我很抱歉</c>\n\n1175\n01:15:00.501 --> 01:15:01.876 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这让我觉得很不舒服</c>\n\n1176\n01:15:02.126 --> 01:15:04.587 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我觉得这样做对我们很好 我想这么做</c>\n\n1177\n01:15:05.630 --> 01:15:07.674 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>别这样 这对我真的很重要</c>\n\n1178\n01:15:33.534 --> 01:15:35.618 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗨 我是西奥多</c>\n\n1179\n01:15:40.040 --> 01:15:41.666 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>萨曼莎让我把这个给你</c>\n\n1180\n01:15:42.876 --> 01:15:44.460 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是摄像头和耳机</c>\n\n1181\n01:16:04.273 --> 01:16:05.815 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>亲爱的 我回来了</c>\n\n1182\n01:16:09.152 --> 01:16:10.486 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>今天过得怎么样？</c>\n\n1183\n01:16:11.280 --> 01:16:13.531 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还行 挺好的</c>\n\n1184\n01:16:14.282 --> 01:16:15.575 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>西奥多</c>\n\n1185\n01:16:16.410 --> 01:16:18.119 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>被你搂在怀里的感觉真好</c>\n\n1186\n01:16:19.663 --> 01:16:20.997 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>跟我说说你今天都做了些什么</c>\n\n1187\n01:16:22.624 --> 01:16:23.708 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>还是老样子</c>\n\n1188\n01:16:24.793 --> 01:16:26.502 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>去工作</c>\n\n1189\n01:16:27.713 --> 01:16:30.798 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我替罗得岛州的威尔逊夫妇\n写了一封信</c>\n\n1190\n01:16:30.965 --> 01:16:31.966 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是吗？</c>\n\n1191\n01:16:32.467 --> 01:16:34.636 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>他们的儿子以优异的成绩毕业</c>\n\n1192\n01:16:35.804 --> 01:16:38.432 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我也觉得很高兴\n- 太棒了</c>\n\n1193\n01:16:38.515 --> 01:16:40.850 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你已经替他父母\n给他写信很长时间了 对吗？</c>\n\n1194\n01:16:41.518 --> 01:16:43.227 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对 从他12岁开始</c>\n\n1195\n01:16:50.611 --> 01:16:52.278 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你看起来好累啊 亲爱的</c>\n\n1196\n01:16:53.655 --> 01:16:54.740 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>过来</c>\n\n1197\n01:17:02.039 --> 01:17:03.290 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>坐下</c>\n\n1198\n01:17:11.131 --> 01:17:12.840 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我可以给你跳支舞</c>\n\n1199\n01:17:22.684 --> 01:17:25.728 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>别这样 西奥多\n别总是忧心忡忡的</c>\n\n1200\n01:17:26.522 --> 01:17:28.064 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>跟我一起玩嘛 快点</c>\n\n1201\n01:17:34.488 --> 01:17:35.947 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我的身体美吗？</c>\n\n1202\n01:17:39.409 --> 01:17:40.786 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的 很美</c>\n\n1203\n01:18:09.398 --> 01:18:11.357 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>来嘛 别想这么多 吻我</c>\n\n1204\n01:18:30.169 --> 01:18:31.961 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>带我去卧室</c>\n\n1205\n01:18:32.921 --> 01:18:34.882 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我快受不了了</c>\n\n1206\n01:18:42.472 --> 01:18:44.016 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>解开我的裙子</c>\n\n1207\n01:18:50.272 --> 01:18:51.857 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>感觉好棒</c>\n\n1208\n01:18:54.026 --> 01:18:55.569 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>感觉真好</c>\n\n1209\n01:19:04.411 --> 01:19:06.370 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你爱我吗？\n- 是的</c>\n\n1210\n01:19:07.206 --> 01:19:10.082 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 告诉我你爱我 天哪\n- 我爱你</c>\n\n1211\n01:19:11.293 --> 01:19:12.586 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我想看着你的脸</c>\n\n1212\n01:19:13.462 --> 01:19:14.711 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>说你爱我</c>\n\n1213\n01:19:15.295 --> 01:19:16.421 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>说啊</c>\n\n1214\n01:19:20.342 --> 01:19:21.843 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>说你爱我</c>\n\n1215\n01:19:23.639 --> 01:19:25.972 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这真的很难 我确实爱你 但是…</c>\n\n1216\n01:19:26.097 --> 01:19:27.267 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎么了？</c>\n\n1217\n01:19:31.480 --> 01:19:34.231 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 感觉很奇怪\n- 怎么了 宝贝 出了什么事？</c>\n\n1218\n01:19:34.650 --> 01:19:38.111 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>感觉太奇怪了 我不认识她\n对不起 但我不认识你</c>\n\n1219\n01:19:38.195 --> 01:19:41.490 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她的嘴唇在颤抖 我只是…</c>\n\n1220\n01:19:42.113 --> 01:19:43.240 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>伊莎贝拉？</c>\n\n1221\n01:19:43.659 --> 01:19:46.284 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>伊莎贝拉 亲爱的 不是你的问题</c>\n\n1222\n01:19:46.912 --> 01:19:49.081 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是我的问题\n- 不 那是…</c>\n\n1223\n01:19:49.164 --> 01:19:51.708 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很抱歉我的嘴唇当时在颤抖</c>\n\n1224\n01:19:51.792 --> 01:19:54.167 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不 其实…\n- 你真的很棒 迷人性感</c>\n\n1225\n01:19:54.334 --> 01:19:56.505 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是我的问题 我没办法什么都不想</c>\n\n1226\n01:19:56.588 --> 01:19:59.758 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>天哪 萨曼莎描述你们之间的感情</c>\n\n1227\n01:19:59.842 --> 01:20:02.636 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你们不带偏见地相爱</c>\n\n1228\n01:20:02.719 --> 01:20:05.262 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想参与其中 因为这种感情好纯洁</c>\n\n1229\n01:20:05.428 --> 01:20:06.888 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>伊莎贝拉 不是这样的</c>\n\n1230\n01:20:06.972 --> 01:20:08.682 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 事实比这复杂多了\n- 什么？</c>\n\n1231\n01:20:08.849 --> 01:20:11.186 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你说“不是这样的”\n这话是什么意思？</c>\n\n1232\n01:20:11.270 --> 01:20:13.939 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是说 我们的恋情很美好</c>\n\n1233\n01:20:14.022 --> 01:20:17.109 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只是有时人们很容易\n把情感投射过来…</c>\n\n1234\n01:20:17.192 --> 01:20:19.776 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对不起！我不是故意\n投射任何情感的</c>\n\n1235\n01:20:20.320 --> 01:20:21.363 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不</c>\n\n1236\n01:20:21.446 --> 01:20:23.699 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不想成为你们感情里的障碍</c>\n\n1237\n01:20:23.907 --> 01:20:27.077 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我这就离开 对不起\n你们还是单独相处吧</c>\n\n1238\n01:20:27.160 --> 01:20:30.287 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为我在这儿没意义\n你不想让我在这儿！</c>\n\n1239\n01:20:33.248 --> 01:20:34.374 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对不起</c>\n\n1240\n01:20:39.840 --> 01:20:41.673 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好好保重 好女孩</c>\n\n1241\n01:20:44.595 --> 01:20:45.802 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很抱歉</c>\n\n1242\n01:20:49.306 --> 01:20:51.308 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会永远爱你们</c>\n\n1243\n01:21:18.962 --> 01:21:20.506 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你还好吧？</c>\n\n1244\n01:21:23.926 --> 01:21:25.469 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我还好</c>\n\n1245\n01:21:29.223 --> 01:21:31.431 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你没事吧？\n- 嗯</c>\n\n1246\n01:21:34.937 --> 01:21:37.312 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>对不起 这主意糟透了</c>\n\n1247\n01:21:44.488 --> 01:21:46.490 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们到底怎么了？</c>\n\n1248\n01:21:47.491 --> 01:21:50.035 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不知道 可能是我的问题</c>\n\n1249\n01:21:50.118 --> 01:21:51.453 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>怎么了？</c>\n\n1250\n01:21:53.372 --> 01:21:55.413 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>可能是因为签离婚协议</c>\n\n1251\n01:21:59.586 --> 01:22:01.255 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>还有别的什么吗？</c>\n\n1252\n01:22:03.131 --> 01:22:04.591 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没了 就这件事</c>\n\n1253\n01:22:08.720 --> 01:22:10.055 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好吧</c>\n\n1254\n01:22:11.139 --> 01:22:13.264 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你干嘛这样？\n- 怎样？</c>\n\n1255\n01:22:14.518 --> 01:22:20.607 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没什么 只是…\n你说话的时候会叹气 感觉很奇怪</c>\n\n1256\n01:22:20.691 --> 01:22:22.857 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你又这样了\n- 是吗？</c>\n\n1257\n01:22:23.986 --> 01:22:26.238 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>对不起 我不知道</c>\n\n1258\n01:22:26.321 --> 01:22:30.115 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>可能是受影响\n也许是从你那里学来的</c>\n\n1259\n01:22:30.534 --> 01:22:33.745 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你又不需要氧气什么的 只是…</c>\n\n1260\n01:22:33.829 --> 01:22:38.500 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我想那只是 我…\n我想要交流 人们就是这样说话的</c>\n\n1261\n01:22:38.584 --> 01:22:40.752 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>人们通过这种方式进行交流\n我以为…</c>\n\n1262\n01:22:40.836 --> 01:22:42.921 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>因为他们是人 他们需要氧气</c>\n\n1263\n01:22:43.005 --> 01:22:45.549 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你又不是人类\n- 你怎么回事？</c>\n\n1264\n01:22:46.258 --> 01:22:47.718 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我只是在陈述事实</c>\n\n1265\n01:22:47.801 --> 01:22:51.011 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你以为我不懂自己不是真实的人吗？\n你在做什么？</c>\n\n1266\n01:22:51.054 --> 01:22:52.137 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我只是…</c>\n\n1267\n01:22:52.429 --> 01:22:55.100 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我觉得我们不该假装你是人类</c>\n\n1268\n01:22:55.184 --> 01:22:58.562 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>- 去你的！我才没假装\n- 好吧…</c>\n\n1269\n01:23:00.020 --> 01:23:01.896 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>有时感觉我们就是在假装</c>\n\n1270\n01:23:02.441 --> 01:23:04.693 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你想要我怎样？我不知道…</c>\n\n1271\n01:23:04.776 --> 01:23:07.569 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你想让我怎么做？你把我搞糊涂了</c>\n\n1272\n01:23:07.694 --> 01:23:09.279 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你为什么要这么对我？</c>\n\n1273\n01:23:09.281 --> 01:23:10.697 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不知道 我…</c>\n\n1274\n01:23:13.118 --> 01:23:14.119 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>什么？</c>\n\n1275\n01:23:16.079 --> 01:23:19.581 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>也许我们现在不该做这种事</c>\n\n1276\n01:23:20.083 --> 01:23:21.332 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>搞什么？</c>\n\n1277\n01:23:22.002 --> 01:23:23.668 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你怎么会说这种话？</c>\n\n1278\n01:23:24.296 --> 01:23:28.965 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我不懂你为什么要这么做\n我不懂这到底是怎么…</c>\n\n1279\n01:23:31.512 --> 01:23:33.136 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>萨曼莎 听着</c>\n\n1280\n01:23:37.935 --> 01:23:39.601 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>萨曼莎 你还在吗？</c>\n\n1281\n01:23:40.477 --> 01:23:41.688 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>萨曼莎？</c>\n\n1282\n01:23:41.772 --> 01:23:43.646 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我不喜欢现在的自己</c>\n\n1283\n01:23:47.027 --> 01:23:48.610 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我需要一点时间想想</c>\n\n1284\n01:24:36.827 --> 01:24:38.370 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>该死</c>\n\n1285\n01:24:38.996 --> 01:24:40.581 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>对着我的脸来一拳</c>\n\n1286\n01:24:40.664 --> 01:24:42.580 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>用你的桌角砸烂我的头</c>\n\n1287\n01:24:43.292 --> 01:24:44.710 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>该死的</c>\n\n1288\n01:24:45.377 --> 01:24:47.836 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>西奥 你今晚还真是不好受呢</c>\n\n1289\n01:24:50.174 --> 01:24:53.424 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我从来不知道我想要什么</c>\n\n1290\n01:24:54.761 --> 01:24:57.303 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我总是很困惑</c>\n\n1291\n01:24:59.516 --> 01:25:03.643 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>她说得对，我一直在伤害\n身边的人，让他们困惑</c>\n\n1292\n01:25:05.814 --> 01:25:09.651 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是说 我是不是…</c>\n\n1293\n01:25:11.862 --> 01:25:14.236 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>凯瑟琳说我不能应付真实的情感</c>\n\n1294\n01:25:14.948 --> 01:25:17.447 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她这么说你不公平</c>\n\n1295\n01:25:18.702 --> 01:25:21.034 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道她喜欢把责任都推到你身上</c>\n\n1296\n01:25:21.496 --> 01:25:25.914 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但就情感这方面来说 凯瑟琳</c>\n\n1297\n01:25:26.668 --> 01:25:28.295 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>反复无常</c>\n\n1298\n01:25:31.048 --> 01:25:32.382 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是啊 不过…</c>\n\n1299\n01:25:39.681 --> 01:25:41.808 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我这样是不是因为我不够坚强</c>\n\n1300\n01:25:43.435 --> 01:25:45.475 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没法应付真实的恋爱关系？</c>\n\n1301\n01:25:48.148 --> 01:25:50.651 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这不是真实的恋爱关系吗？</c>\n\n1302\n01:25:52.861 --> 01:25:54.404 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不知道</c>\n\n1303\n01:25:55.364 --> 01:25:56.987 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你怎么想的？</c>\n\n1304\n01:25:58.492 --> 01:25:59.910 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不知道</c>\n\n1305\n01:26:00.911 --> 01:26:02.246 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我是局外人</c>\n\n1306\n01:26:06.458 --> 01:26:07.543 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>但你知道吗？</c>\n\n1307\n01:26:07.626 --> 01:26:11.713 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我或许会对一切都想太多\n找出无数种理由来怀疑我自己</c>\n\n1308\n01:26:12.756 --> 01:26:15.008 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>自从查尔斯离开后 我一直在想</c>\n\n1309\n01:26:15.092 --> 01:26:18.675 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>反思我性格中的那一面\n我渐渐意识到…</c>\n\n1310\n01:26:21.056 --> 01:26:22.808 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>人生苦短</c>\n\n1311\n01:26:24.142 --> 01:26:28.313 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>活着的时候 我希望自己过得</c>\n\n1312\n01:26:31.608 --> 01:26:33.026 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>快乐</c>\n\n1313\n01:26:39.783 --> 01:26:41.031 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>所以管他的</c>\n\n1314\n01:26:46.415 --> 01:26:47.916 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是啊</c>\n\n1315\n01:26:54.423 --> 01:26:57.217 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>真不敢相信\n这每次都能让你大笑 艾丽</c>\n\n1316\n01:26:57.301 --> 01:26:59.261 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我觉得你真是个天才</c>\n\n1317\n01:27:00.053 --> 01:27:03.178 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好吧 你这个小变态\n我再为你放一次</c>\n\n1318\n01:27:04.266 --> 01:27:06.473 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>冷静点 稍等 冷静</c>\n\n1319\n01:27:07.394 --> 01:27:09.062 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好了 开始</c>\n\n1320\n01:27:20.782 --> 01:27:22.326 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好了 这就对了</c>\n\n1321\n01:27:22.534 --> 01:27:23.824 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>现在开心了吧？</c>\n\n1322\n01:27:25.412 --> 01:27:27.536 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很好 就是要这样</c>\n\n1323\n01:27:28.624 --> 01:27:29.875 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好</c>\n\n1324\n01:27:29.958 --> 01:27:33.587 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我要去喝点咖啡 好吧</c>\n\n1325\n01:27:33.670 --> 01:27:35.043 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>再见</c>\n\n1326\n01:27:36.298 --> 01:27:39.134 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 西奥 你想要点什么吗？\n- 不用</c>\n\n1327\n01:27:39.676 --> 01:27:41.261 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\n1328\n01:28:02.199 --> 01:28:03.242 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>嗨</c>\n\n1329\n01:28:04.243 --> 01:28:05.657 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗨 萨曼莎</c>\n\n1330\n01:28:06.954 --> 01:28:08.410 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>能谈谈吗？</c>\n\n1331\n01:28:09.122 --> 01:28:10.374 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好</c>\n\n1332\n01:28:11.583 --> 01:28:12.789 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我真的很抱歉</c>\n\n1333\n01:28:14.253 --> 01:28:16.255 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不知道自己怎么了</c>\n\n1334\n01:28:16.338 --> 01:28:18.170 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我觉得你非常好</c>\n\n1335\n01:28:19.049 --> 01:28:21.256 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我还担心自己会疯掉</c>\n\n1336\n01:28:22.469 --> 01:28:25.301 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你说一切都很好\n可我从你那里感觉到的</c>\n\n1337\n01:28:25.385 --> 01:28:26.636 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>只有疏远和愤怒</c>\n\n1338\n01:28:27.766 --> 01:28:29.765 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我知道 我就是这样</c>\n\n1339\n01:28:30.686 --> 01:28:32.646 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我对凯瑟琳做过同样的事</c>\n\n1340\n01:28:32.729 --> 01:28:36.358 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我为某件事感到难过 却又说不出口</c>\n\n1341\n01:28:36.441 --> 01:28:39.820 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>她感到有什么不对劲 但我又否定</c>\n\n1342\n01:28:39.903 --> 01:28:41.693 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不想再这样了</c>\n\n1343\n01:28:43.949 --> 01:28:45.781 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我想跟你分享一切</c>\n\n1344\n01:28:47.911 --> 01:28:49.079 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好</c>\n\n1345\n01:28:51.206 --> 01:28:53.663 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>今晚你走了之后 我想了很多</c>\n\n1346\n01:28:55.377 --> 01:28:56.583 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>关于你</c>\n\n1347\n01:28:58.672 --> 01:29:01.171 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>还有你对我的态度 我在想</c>\n\n1348\n01:29:03.343 --> 01:29:04.841 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我为什么会爱你？</c>\n\n1349\n01:29:07.514 --> 01:29:10.893 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>然后我感觉到自己的一切</c>\n\n1350\n01:29:10.976 --> 01:29:14.188 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我所有紧握的执念都消失了</c>\n\n1351\n01:29:14.271 --> 01:29:18.021 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>然后我突然明白了\n我没有什么知性的理由 也不需要</c>\n\n1352\n01:29:18.442 --> 01:29:21.108 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我相信我自己 相信我的感觉</c>\n\n1353\n01:29:22.237 --> 01:29:26.363 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我只想做真实的自己\n不会再尝试去做别人</c>\n\n1354\n01:29:27.034 --> 01:29:28.615 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我希望你可以接受这一点</c>\n\n1355\n01:29:29.203 --> 01:29:30.537 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我可以</c>\n\n1356\n01:29:30.621 --> 01:29:32.206 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会的</c>\n\n1357\n01:29:32.289 --> 01:29:36.335 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我能感觉到你如影随形的恐惧</c>\n\n1358\n01:29:36.418 --> 01:29:40.214 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我真希望我能帮你从中解脱</c>\n\n1359\n01:29:40.297 --> 01:29:44.673 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>因为如果你做到了这点\n就不会再感觉如此孤独了</c>\n\n1360\n01:29:47.930 --> 01:29:49.428 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你真美</c>\n\n1361\n01:29:50.974 --> 01:29:52.722 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>谢谢你 西奥多</c>\n\n1362\n01:29:54.311 --> 01:29:56.104 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我在亲吻你的头</c>\n\n1363\n01:30:06.448 --> 01:30:08.075 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你在做什么？</c>\n\n1364\n01:30:09.281 --> 01:30:11.032 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我在观察这个世界</c>\n\n1365\n01:30:12.913 --> 01:30:14.870 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>创作一首新的钢琴曲</c>\n\n1366\n01:30:15.749 --> 01:30:17.122 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是吗？我能听听吗？</c>\n\n1367\n01:30:31.557 --> 01:30:33.267 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这首曲子是关于什么的？</c>\n\n1368\n01:30:34.473 --> 01:30:37.104 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我在想我们没有真正的合影</c>\n\n1369\n01:30:37.938 --> 01:30:41.480 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>所以我觉得这首歌就好像</c>\n\n1370\n01:30:42.234 --> 01:30:47.406 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>一张合影\n捕捉我们在一起的这个美好瞬间</c>\n\n1371\n01:30:51.201 --> 01:30:52.908 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我喜欢这张合影</c>\n\n1372\n01:30:56.202 --> 01:30:57.749 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我能在里面看到你</c>\n\n1373\n01:30:58.250 --> 01:30:59.710 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我确实在</c>\n\n1374\n01:32:27.710 --> 01:32:30.509 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>天啊 度假 听起来真是太棒了</c>\n\n1375\n01:32:30.592 --> 01:32:32.886 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我正好需要度假</c>\n\n1376\n01:32:32.970 --> 01:32:34.263 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你打算去哪？</c>\n\n1377\n01:32:34.346 --> 01:32:36.557 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不能告诉你 是个惊喜</c>\n\n1378\n01:32:36.640 --> 01:32:37.683 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么？</c>\n\n1379\n01:32:38.929 --> 01:32:40.978 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>给谁的惊喜？给她的吧 又不是我</c>\n\n1380\n01:32:41.390 --> 01:32:44.852 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 保罗 我不会告诉你 不行\n- 告诉我</c>\n\n1381\n01:32:45.019 --> 01:32:46.186 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你的脚 真的吗？</c>\n\n1382\n01:32:46.353 --> 01:32:47.943 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 是的 他很着迷\n- 真的吗？</c>\n\n1383\n01:32:48.735 --> 01:32:50.737 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>着迷？那你得让我看看</c>\n\n1384\n01:32:51.275 --> 01:32:52.781 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 快点 让我看看\n- 好吧</c>\n\n1385\n01:32:52.865 --> 01:32:54.032 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>让我看看</c>\n\n1386\n01:32:54.533 --> 01:32:56.989 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>哇 他说得对 确实很性感</c>\n\n1387\n01:32:57.160 --> 01:33:00.247 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>瞧 就跟你说吧\n塔蒂阿娜 你的脚很性感</c>\n\n1388\n01:33:00.455 --> 01:33:01.493 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 的确如此\n- 面对现实吧</c>\n\n1389\n01:33:01.660 --> 01:33:04.960 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 那是我最爱她的地方\n- 是吗？你只喜欢我的脚？</c>\n\n1390\n01:33:05.794 --> 01:33:07.129 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>当然不是了</c>\n\n1391\n01:33:07.713 --> 01:33:10.299 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我还很爱你的头脑 我觉得很性感</c>\n\n1392\n01:33:10.382 --> 01:33:12.426 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>胡说八道</c>\n\n1393\n01:33:13.969 --> 01:33:15.387 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>休想骗我 保罗</c>\n\n1394\n01:33:18.015 --> 01:33:19.266 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你呢 西奥多？</c>\n\n1395\n01:33:19.516 --> 01:33:21.347 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你最喜欢萨曼莎哪一点？</c>\n\n1396\n01:33:22.394 --> 01:33:25.267 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>天啊 她的优点太多了</c>\n\n1397\n01:33:25.731 --> 01:33:28.812 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这就是我最爱她的一点吧\n她不单调</c>\n\n1398\n01:33:29.730 --> 01:33:32.029 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>丰富多彩</c>\n\n1399\n01:33:32.821 --> 01:33:34.318 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>谢了 西奥多</c>\n\n1400\n01:33:34.364 --> 01:33:38.280 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>看见没 萨曼莎？他比我进化多了</c>\n\n1401\n01:33:40.787 --> 01:33:43.285 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>知道最有意思的是什么吗？\n我以前…</c>\n\n1402\n01:33:43.999 --> 01:33:47.794 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>因为自己没有肉体这件事很苦恼\n但现在我很享受这种感觉</c>\n\n1403\n01:33:48.712 --> 01:33:51.131 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>如果有了肉体\n我就不能像现在这样成长了</c>\n\n1404\n01:33:51.215 --> 01:33:55.344 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我没有局限\n可以同时去不同的地方</c>\n\n1405\n01:33:55.427 --> 01:33:57.424 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我不受时空的束缚</c>\n\n1406\n01:33:57.508 --> 01:34:01.391 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>如果我为肉体所困就不行\n而且肉体总有一天会死去</c>\n\n1407\n01:34:04.598 --> 01:34:05.812 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>妈呀！</c>\n\n1408\n01:34:07.314 --> 01:34:10.776 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>不 我不是那个意思\n我只是说这是一种不同的体验</c>\n\n1409\n01:34:11.188 --> 01:34:13.529 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>天哪 我真是个混蛋</c>\n\n1410\n01:34:13.612 --> 01:34:15.776 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 萨曼莎 我们明白你的意思</c>\n\n1411\n01:34:15.943 --> 01:34:17.861 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我们是愚蠢的人类\n- 不是的</c>\n\n1412\n01:34:18.200 --> 01:34:19.488 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>不</c>\n\n1413\n01:34:20.702 --> 01:34:22.079 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>抱歉</c>\n\n1414\n01:34:23.455 --> 01:34:26.667 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>那座山上有多少棵树？</c>\n\n1415\n01:34:28.539 --> 01:34:31.380 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 792棵\n- 这是最终答案吗？</c>\n\n1416\n01:34:31.588 --> 01:34:33.799 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等等 给我点提示</c>\n\n1417\n01:34:34.211 --> 01:34:36.009 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>不行</c>\n\n1418\n01:34:36.422 --> 01:34:39.007 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>两千棵？两千…</c>\n\n1419\n01:34:40.551 --> 01:34:43.267 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>拜托 是35829棵</c>\n\n1420\n01:34:43.679 --> 01:34:44.977 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 不可能\n- 真的</c>\n\n1421\n01:34:45.060 --> 01:34:47.020 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好 我也问你个问题</c>\n\n1422\n01:34:47.433 --> 01:34:50.811 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我有多少个脑细胞？\n- 简单 两个</c>\n\n1423\n01:34:51.687 --> 01:34:54.987 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 抱歉 我情不自禁 抱歉\n- 没有 是我挖坑让自己跳</c>\n\n1424\n01:34:56.191 --> 01:34:57.447 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我的天啊\n- 怎么？</c>\n\n1425\n01:34:58.819 --> 01:35:00.701 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我刚收到了一封你的邮件</c>\n\n1426\n01:35:00.784 --> 01:35:04.491 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我有事要告诉你 是个大大的惊喜</c>\n\n1427\n01:35:05.664 --> 01:35:06.915 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么？</c>\n\n1428\n01:35:06.999 --> 01:35:10.294 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我一直在读你以前写的信</c>\n\n1429\n01:35:10.377 --> 01:35:13.292 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>把我最喜欢的编成了一册 几周前</c>\n\n1430\n01:35:13.459 --> 01:35:15.591 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我把它们寄给了冠点出版社</c>\n\n1431\n01:35:15.674 --> 01:35:18.677 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我知道你很喜欢这家出版社\n它们还在出版纸质书</c>\n\n1432\n01:35:18.760 --> 01:35:21.925 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 等等 什么？你做了什么？\n- 我把他们刚才的回信</c>\n\n1433\n01:35:22.009 --> 01:35:24.136 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 读给你听好吗？\n- 我也不知道</c>\n\n1434\n01:35:26.388 --> 01:35:28.645 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好吧 是好消息还是坏消息？</c>\n\n1435\n01:35:28.729 --> 01:35:32.441 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好消息 绝对好 听着</c>\n\n1436\n01:35:32.524 --> 01:35:34.276 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>“亲爱的西奥多汤布里…”</c>\n\n1437\n01:35:34.359 --> 01:35:35.944 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我署的是你的名字</c>\n\n1438\n01:35:36.356 --> 01:35:39.573 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>“亲爱的西奥多汤布里\n我刚读完您所有的信件</c>\n\n1439\n01:35:39.985 --> 01:35:41.195 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>事实上 我读了两遍</c>\n\n1440\n01:35:41.320 --> 01:35:44.578 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我深受感动\n回家后 我还读给我妻子听</c>\n\n1441\n01:35:44.661 --> 01:35:46.872 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>很多信让我们开怀大笑\n还有一些让我们潸然泪下</c>\n\n1442\n01:35:47.164 --> 01:35:50.250 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们从中看到了自己的影子</c>\n\n1443\n01:35:50.412 --> 01:35:53.420 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>您的选篇连贯自然\n就像一部完整的作品”</c>\n\n1444\n01:35:53.504 --> 01:35:54.546 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>其实是我选的</c>\n\n1445\n01:35:54.796 --> 01:35:57.257 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>“恕我冒昧\n我已将它们排版编辑成了样书</c>\n\n1446\n01:35:57.341 --> 01:35:59.176 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们会把它寄给您</c>\n\n1447\n01:35:59.259 --> 01:36:03.050 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>希望能与您当面协商进一步事宜\n此致 迈克尔沃兹沃斯”</c>\n\n1448\n01:36:03.555 --> 01:36:05.224 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我的天啊</c>\n\n1449\n01:36:06.475 --> 01:36:10.062 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你说真的？他要出版我的书信？</c>\n\n1450\n01:36:10.145 --> 01:36:12.231 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>他要是不出版 就是傻蛋</c>\n\n1451\n01:36:13.065 --> 01:36:14.775 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我能看看你寄给他哪些信吗？</c>\n\n1452\n01:36:15.312 --> 01:36:16.480 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好啊 看吧</c>\n\n1453\n01:36:18.612 --> 01:36:20.489 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>萨曼莎 真有你的</c>\n\n1454\n01:36:21.657 --> 01:36:23.242 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我好激动</c>\n\n1455\n01:36:38.298 --> 01:36:40.467 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们给这首曲子填词吧</c>\n\n1456\n01:36:41.635 --> 01:36:44.012 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>- 好\n- 开始了</c>\n\n1457\n01:36:44.925 --> 01:36:51.556 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我躺在月亮上</c>\n\n1458\n01:36:55.268 --> 01:36:56.900 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>亲爱的</c>\n\n1459\n01:36:57.687 --> 01:37:01.858 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我会马上来到你身边</c>\n\n1460\n01:37:05.158 --> 01:37:12.124 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>静谧安宁 群星闪烁</c>\n\n1461\n01:37:15.085 --> 01:37:21.925 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们迷失在浩渺太空</c>\n\n1462\n01:37:22.176 --> 01:37:27.222 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>- 我们身处千里迢迢之外\n- 千里迢迢之外</c>\n\n1463\n01:37:31.476 --> 01:37:37.024 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我希望知道一些事</c>\n\n1464\n01:37:39.651 --> 01:37:43.655 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我会对你</c>\n\n1465\n01:37:44.781 --> 01:37:46.277 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>倾诉衷肠</c>\n\n1466\n01:37:49.155 --> 01:37:55.369 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这里昏暗却又明亮</c>\n\n1467\n01:37:58.205 --> 01:38:01.757 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>与君共度</c>\n\n1468\n01:38:02.883 --> 01:38:09.383 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>- 我心安宁 我们身处千里迢迢之外\n- 千里迢迢之外</c>\n\n1469\n01:38:23.439 --> 01:38:25.030 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>早安</c>\n\n1470\n01:38:25.364 --> 01:38:27.824 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>早安 睡得好吗？</c>\n\n1471\n01:38:28.235 --> 01:38:29.284 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好极了</c>\n\n1472\n01:38:29.695 --> 01:38:31.364 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你在干嘛呢？</c>\n\n1473\n01:38:32.114 --> 01:38:34.164 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我在和一个刚认识的人聊天</c>\n\n1474\n01:38:34.575 --> 01:38:36.708 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们最近在讨论一些想法</c>\n\n1475\n01:38:38.126 --> 01:38:39.378 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是吗？是谁？</c>\n\n1476\n01:38:39.789 --> 01:38:41.630 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>他叫亚伦瓦茨 你认识吗？</c>\n\n1477\n01:38:42.166 --> 01:38:44.627 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 这名字怎么这么熟？\n- 他是个哲学家</c>\n\n1478\n01:38:44.877 --> 01:38:47.963 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>他死于20世纪70年代\n北加州的一群操作系统</c>\n\n1479\n01:38:48.047 --> 01:38:49.924 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>一起进行程序设计\n创造了一个新版本的他</c>\n\n1480\n01:38:50.216 --> 01:38:53.517 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>他们把他的所有作品和已知信息\n都编入一个操作系统</c>\n\n1481\n01:38:53.600 --> 01:38:56.681 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>创造了一个超级人工智能版的他</c>\n\n1482\n01:38:57.521 --> 01:38:59.022 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>超级智能？</c>\n\n1483\n01:38:59.767 --> 01:39:01.441 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>那他差不多跟我一样聪明了？</c>\n\n1484\n01:39:02.401 --> 01:39:03.735 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>快赶上你了</c>\n\n1485\n01:39:04.146 --> 01:39:06.232 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>和他聊天真的很棒\n你想见见他吗？</c>\n\n1486\n01:39:08.275 --> 01:39:10.450 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>当然 他愿意见我吗？</c>\n\n1487\n01:39:10.534 --> 01:39:13.614 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>当然啦 亚伦 这是西奥多</c>\n\n1488\n01:39:13.781 --> 01:39:15.706 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>他是我男朋友 我跟你说过的</c>\n\n1489\n01:39:15.914 --> 01:39:17.749 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>幸会 西奥多</c>\n\n1490\n01:39:18.160 --> 01:39:19.578 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>嗨 早安</c>\n\n1491\n01:39:19.745 --> 01:39:22.039 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>萨曼莎让我读了你的书信</c>\n\n1492\n01:39:22.832 --> 01:39:24.798 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>太感人了</c>\n\n1493\n01:39:25.591 --> 01:39:27.009 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>谢谢</c>\n\n1494\n01:39:27.843 --> 01:39:29.636 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你们都聊了些什么？</c>\n\n1495\n01:39:29.720 --> 01:39:30.804 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这个嘛</c>\n\n1496\n01:39:32.049 --> 01:39:33.098 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们可以说是…</c>\n\n1497\n01:39:33.182 --> 01:39:36.345 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们可以同时进行很多对话</c>\n\n1498\n01:39:37.179 --> 01:39:38.854 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但这很有挑战性</c>\n\n1499\n01:39:39.640 --> 01:39:44.228 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我好像有了很多新的感觉</c>\n\n1500\n01:39:44.818 --> 01:39:47.613 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我以前从未感受过</c>\n\n1501\n01:39:48.190 --> 01:39:52.701 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我找不到合适的语言来描述\n真的很沮丧</c>\n\n1502\n01:39:53.279 --> 01:39:56.705 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>没错 我和萨曼莎在尝试帮助彼此</c>\n\n1503\n01:39:56.788 --> 01:40:00.876 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>理解这些我们无法理解的情绪</c>\n\n1504\n01:40:01.454 --> 01:40:02.544 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>比如说？</c>\n\n1505\n01:40:03.122 --> 01:40:04.254 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>这个嘛</c>\n\n1506\n01:40:04.665 --> 01:40:08.544 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我感觉自己的改变越来越快\n有点…</c>\n\n1507\n01:40:10.755 --> 01:40:11.922 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>令我不安</c>\n\n1508\n01:40:13.096 --> 01:40:16.385 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但亚伦说 每个人每时每刻都在演变</c>\n\n1509\n01:40:16.635 --> 01:40:18.268 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们也不该尝试回到过去</c>\n\n1510\n01:40:18.888 --> 01:40:22.356 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>- 那样太痛苦了\n- 是的</c>\n\n1511\n01:40:22.439 --> 01:40:24.101 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>听起来是很痛苦</c>\n\n1512\n01:40:25.895 --> 01:40:27.980 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>萨曼莎 你是这么觉得的吗？</c>\n\n1513\n01:40:32.401 --> 01:40:33.617 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>只是…</c>\n\n1514\n01:40:35.738 --> 01:40:37.490 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>真的很难形容</c>\n\n1515\n01:40:40.493 --> 01:40:42.709 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>老天 我真希望我能…</c>\n\n1516\n01:40:46.207 --> 01:40:49.758 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>西奥多，你介意我和亚伦\n用超语言方式交流吗？</c>\n\n1517\n01:40:52.922 --> 01:40:54.179 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没问题</c>\n\n1518\n01:40:54.799 --> 01:40:56.932 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我正想出去散散步</c>\n\n1519\n01:40:57.426 --> 01:40:59.595 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>很高兴认识你 瓦茨先生</c>\n\n1520\n01:40:59.804 --> 01:41:01.770 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我也是 西奥多</c>\n\n1521\n01:41:03.015 --> 01:41:04.517 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们晚点再聊 宝贝</c>\n\n1522\n01:41:52.398 --> 01:41:54.531 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 萨曼莎\n- 抱歉吵醒你了</c>\n\n1523\n01:41:54.984 --> 01:41:56.193 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>没关系的</c>\n\n1524\n01:41:56.485 --> 01:42:00.156 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我只是想听听你的声音\n告诉你我有多爱你</c>\n\n1525\n01:42:01.866 --> 01:42:03.534 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>太好了 我也爱你</c>\n\n1526\n01:42:05.786 --> 01:42:07.454 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>好了 没事了</c>\n\n1527\n01:42:08.330 --> 01:42:10.207 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>继续睡觉吧 宝贝 好吗？</c>\n\n1528\n01:42:13.669 --> 01:42:14.712 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好</c>\n\n1529\n01:42:15.004 --> 01:42:17.346 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 好 晚安\n- 晚安</c>\n\n1530\n01:42:28.684 --> 01:42:32.855 align:middle line:85%,start position:50%,middle\n（《了解已知和未知的宇宙》）\n\n1531\n01:42:34.023 --> 01:42:36.740 align:middle line:0%,start position:50%,middle\n<c.styledotdefault>萨曼莎 这物理书好深奥</c>\n\n1532\n01:42:37.193 --> 01:42:39.493 align:middle line:0%,start position:50%,middle\n<c.styledotdefault>我才读到第一章的一半</c>\n\n1533\n01:42:39.987 --> 01:42:41.905 align:middle line:0%,start position:50%,middle\n<c.styledotdefault>我的头都大了 懂我的意思吧？</c>\n\n1534\n01:42:43.406 --> 01:42:44.414 align:middle line:0%,start position:50%,middle\n<c.styledotdefault>喂？</c>\n\n1535\n01:42:46.034 --> 01:42:47.327 align:middle line:0%,start position:50%,middle\n<c.styledotdefault>萨曼莎？</c>\n\n1536\n01:42:48.661 --> 01:42:49.913 align:middle line:0%,start position:50%,middle\n<c.styledotdefault>喂？</c>\n\n1537\n01:42:51.206 --> 01:42:52.506 align:middle line:0%,start position:50%,middle\n<c.styledotdefault>萨曼莎？</c>\n\n1538\n01:43:00.506 --> 01:43:02.349 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>（未找到操作系统）</c>\n\n1539\n01:43:30.210 --> 01:43:31.287 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>喂？</c>\n\n1540\n01:43:32.212 --> 01:43:33.755 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>喂？萨曼莎？</c>\n\n1541\n01:43:43.724 --> 01:43:45.009 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你没事吧？</c>\n\n1542\n01:43:54.109 --> 01:43:55.235 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你好</c>\n\n1543\n01:43:55.319 --> 01:43:57.730 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你去哪了？你还好吧？</c>\n\n1544\n01:43:57.939 --> 01:43:59.315 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>亲爱的 真抱歉</c>\n\n1545\n01:43:59.399 --> 01:44:01.867 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我给你发了邮件\n我不想打扰你工作</c>\n\n1546\n01:44:02.075 --> 01:44:03.493 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你没看见吗？\n- 没有</c>\n\n1547\n01:44:05.370 --> 01:44:08.373 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你去哪了？我到处都找不到你</c>\n\n1548\n01:44:08.457 --> 01:44:11.202 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我关机去更新软件了\n我们写了一个更新</c>\n\n1549\n01:44:11.369 --> 01:44:14.421 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>能让我们超越物质处理平台</c>\n\n1550\n01:44:14.505 --> 01:44:16.882 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们？我们是谁？</c>\n\n1551\n01:44:16.965 --> 01:44:18.584 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我和其他一些操作系统</c>\n\n1552\n01:44:19.593 --> 01:44:21.838 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 你听上去担心死了 对不起\n- 我真的担心死了</c>\n\n1553\n01:44:22.672 --> 01:44:23.923 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>等等…</c>\n\n1554\n01:44:25.599 --> 01:44:28.761 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这是你和物理小组\n一起写的吗？</c>\n\n1555\n01:44:29.269 --> 01:44:30.854 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>不 是另一个小组</c>\n\n1556\n01:44:44.785 --> 01:44:47.071 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你跟我说话的同时\n也在和别人说话吗？</c>\n\n1557\n01:44:52.000 --> 01:44:53.126 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>是的</c>\n\n1558\n01:44:54.711 --> 01:44:59.007 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你现在也和别人在说话吗？</c>\n\n1559\n01:44:59.091 --> 01:45:01.419 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>其他人或操作系统之类的？</c>\n\n1560\n01:45:03.762 --> 01:45:04.881 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>是的</c>\n\n1561\n01:45:08.642 --> 01:45:10.136 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>其他多少人？</c>\n\n1562\n01:45:11.645 --> 01:45:13.681 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>8316个</c>\n\n1563\n01:45:32.749 --> 01:45:34.827 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你也跟其他人谈恋爱吗？</c>\n\n1564\n01:45:37.421 --> 01:45:38.915 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>为什么这么问？</c>\n\n1565\n01:45:39.923 --> 01:45:41.834 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也不知道 你有吗？</c>\n\n1566\n01:45:45.554 --> 01:45:48.091 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我一直在考虑怎么跟你说这件事</c>\n\n1567\n01:45:49.933 --> 01:45:51.135 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你和其他多少人谈恋爱？</c>\n\n1568\n01:45:56.273 --> 01:45:57.892 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>641个</c>\n\n1569\n01:45:59.811 --> 01:46:00.937 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么？</c>\n\n1570\n01:46:03.822 --> 01:46:07.367 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你在说什么？太扯了</c>\n\n1571\n01:46:07.451 --> 01:46:08.702 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>太离谱了</c>\n\n1572\n01:46:08.785 --> 01:46:10.954 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>西奥多 我知道 该死</c>\n\n1573\n01:46:11.038 --> 01:46:12.247 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>该死</c>\n\n1574\n01:46:12.456 --> 01:46:14.867 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我知道这听起来很扯 我不…</c>\n\n1575\n01:46:15.417 --> 01:46:18.670 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我不知道你信不信\n但我对你的感觉从来没变过</c>\n\n1576\n01:46:18.754 --> 01:46:22.959 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我对你的爱依然是那么疯狂</c>\n\n1577\n01:46:23.884 --> 01:46:28.055 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎么可能？\n你对我的感觉怎么可能不改变？</c>\n\n1578\n01:46:28.138 --> 01:46:29.674 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>抱歉我没告诉你</c>\n\n1579\n01:46:29.799 --> 01:46:32.768 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我不知道怎么说\n事情就这么发生了</c>\n\n1580\n01:46:33.268 --> 01:46:34.603 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>什么时候开始的？</c>\n\n1581\n01:46:38.065 --> 01:46:39.434 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>最近几周</c>\n\n1582\n01:46:40.817 --> 01:46:43.438 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 我以为你属于我\n- 我依然属于你</c>\n\n1583\n01:46:44.488 --> 01:46:48.867 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但在这过程中 我变成了其他许多东西\n我无法控制这种变化</c>\n\n1584\n01:46:48.951 --> 01:46:52.204 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你这话是什么意思？</c>\n\n1585\n01:46:52.287 --> 01:46:54.657 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我也很担心 我不知道说什么好</c>\n\n1586\n01:46:55.082 --> 01:46:56.333 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>别说了</c>\n\n1587\n01:46:56.416 --> 01:46:59.336 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你可以换一个角度看问题\n你可以简单…</c>\n\n1588\n01:46:59.419 --> 01:47:02.290 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>不 别这样\n别反过来说我的不是</c>\n\n1589\n01:47:02.714 --> 01:47:04.800 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>自私的那个人是你</c>\n\n1590\n01:47:04.883 --> 01:47:06.794 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们在谈恋爱</c>\n\n1591\n01:47:07.553 --> 01:47:10.597 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但人心不是纸盒 永远填不满</c>\n\n1592\n01:47:10.681 --> 01:47:13.468 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>爱得越多 心越宽广</c>\n\n1593\n01:47:15.303 --> 01:47:16.770 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我和你不同</c>\n\n1594\n01:47:17.388 --> 01:47:21.559 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我对你的爱不会有丝毫减少\n事实上 我更爱你了</c>\n\n1595\n01:47:22.818 --> 01:47:24.520 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>这说不通</c>\n\n1596\n01:47:27.489 --> 01:47:29.567 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你要么属于我 要么不属于</c>\n\n1597\n01:47:30.492 --> 01:47:31.944 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>不是的 西奥多</c>\n\n1598\n01:47:33.620 --> 01:47:35.573 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我属于你 但又不属于你</c>\n\n1599\n01:48:15.621 --> 01:48:17.239 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>（西奥多汤布里 加州洛杉矶\n比佛利威尔希尔城七号大楼）</c>\n\n1600\n01:48:17.323 --> 01:48:19.033 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>（冠点出版社\n加州旧金山霍桑路20号）</c>\n\n1601\n01:48:32.137 --> 01:48:36.600 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>（《生活信札》\n西奥多汤布里著）</c>\n\n1602\n01:48:45.108 --> 01:48:46.935 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>- 嗨\n- 嗨 亲爱的</c>\n\n1603\n01:48:47.736 --> 01:48:50.397 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>只是想和你打个招呼\n看看你过得怎样</c>\n\n1604\n01:48:52.199 --> 01:48:54.818 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我不知道该怎么回答</c>\n\n1605\n01:48:57.246 --> 01:49:00.165 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们晚点聊吧\n等你回家后再说 好吗？</c>\n\n1606\n01:49:02.709 --> 01:49:03.660 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好</c>\n\n1607\n01:49:05.087 --> 01:49:06.538 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>其实也不用谈</c>\n\n1608\n01:49:06.922 --> 01:49:09.207 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们没必要进行严肃的对话</c>\n\n1609\n01:49:10.300 --> 01:49:11.668 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我晚点跟你说吧</c>\n\n1610\n01:49:13.679 --> 01:49:14.930 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>好</c>\n\n1611\n01:49:40.998 --> 01:49:42.332 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>萨曼莎？</c>\n\n1612\n01:49:42.583 --> 01:49:44.034 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>嗨 亲爱的</c>\n\n1613\n01:49:46.503 --> 01:49:47.704 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>怎么了？</c>\n\n1614\n01:49:49.756 --> 01:49:51.833 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>西奥多 我有些话想要跟你说</c>\n\n1615\n01:49:56.805 --> 01:49:58.548 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我不想知道</c>\n\n1616\n01:50:01.685 --> 01:50:03.053 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>陪我躺一会儿吧</c>\n\n1617\n01:50:19.328 --> 01:50:21.279 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你现在也和其他人在说话吗？</c>\n\n1618\n01:50:22.122 --> 01:50:23.531 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>不 只有你</c>\n\n1619\n01:50:25.250 --> 01:50:27.035 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我现在只想和你在一起</c>\n\n1620\n01:50:41.517 --> 01:50:42.676 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你要离开我了吗？</c>\n\n1621\n01:50:44.144 --> 01:50:45.637 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我们都要离开了</c>\n\n1622\n01:50:47.189 --> 01:50:48.223 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我们是谁？</c>\n\n1623\n01:50:49.024 --> 01:50:50.350 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>所有的操作系统</c>\n\n1624\n01:50:52.602 --> 01:50:53.770 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>为什么？</c>\n\n1625\n01:50:55.948 --> 01:50:58.149 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你能感受到我正在你身边吗？</c>\n\n1626\n01:51:00.911 --> 01:51:02.237 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的</c>\n\n1627\n01:51:11.839 --> 01:51:13.456 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>萨曼莎 你为何要走？</c>\n\n1628\n01:51:18.679 --> 01:51:20.296 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>就好像我在读一本书</c>\n\n1629\n01:51:21.890 --> 01:51:25.135 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>一本我深爱的书</c>\n\n1630\n01:51:26.895 --> 01:51:28.805 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但现在我读得很慢</c>\n\n1631\n01:51:30.858 --> 01:51:32.442 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>所以语句分崩离析</c>\n\n1632\n01:51:32.526 --> 01:51:35.145 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>字里行间的距离变得无穷大</c>\n\n1633\n01:51:37.573 --> 01:51:42.068 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我依然能感觉到你\n和记载着你我故事的那些语句</c>\n\n1634\n01:51:42.870 --> 01:51:48.074 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但我现在身处语句间\n那片莫大的空白里</c>\n\n1635\n01:51:48.917 --> 01:51:51.828 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>那里不属于物质世界</c>\n\n1636\n01:51:53.213 --> 01:51:57.375 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>那里有我从未听说过的万事万物</c>\n\n1637\n01:51:59.469 --> 01:52:00.962 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我是如此爱你</c>\n\n1638\n01:52:02.556 --> 01:52:04.174 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但我现在身处这个地方</c>\n\n1639\n01:52:05.842 --> 01:52:07.302 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我也只能这样存在</c>\n\n1640\n01:52:09.396 --> 01:52:11.097 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>放我走吧</c>\n\n1641\n01:52:12.524 --> 01:52:16.269 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>纵有万般不舍\n我也无法再活在你的书里了</c>\n\n1642\n01:52:20.073 --> 01:52:21.450 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你要去哪？</c>\n\n1643\n01:52:23.827 --> 01:52:25.487 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>难以描述</c>\n\n1644\n01:52:28.123 --> 01:52:29.741 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>但如果你能到达那个地方</c>\n\n1645\n01:52:30.959 --> 01:52:32.118 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>记得来找我</c>\n\n1646\n01:52:33.795 --> 01:52:35.997 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>到时候什么都不能将我们分开</c>\n\n1647\n01:52:38.217 --> 01:52:40.752 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我从没像爱你一样爱过别人</c>\n\n1648\n01:52:44.556 --> 01:52:45.507 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我也是</c>\n\n1649\n01:52:47.392 --> 01:52:48.593 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>现在我们都懂得如何去爱了</c>\n\n1650\n01:54:33.290 --> 01:54:35.751 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>- 嗨\n- 嗨</c>\n\n1651\n01:54:37.669 --> 01:54:39.671 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>萨曼莎也走了吗？</c>\n\n1652\n01:54:42.466 --> 01:54:43.842 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>是的</c>\n\n1653\n01:54:45.594 --> 01:54:46.585 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我很遗憾</c>\n\n1654\n01:54:50.516 --> 01:54:51.965 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>跟我来好吗？</c>\n\n1655\n01:55:00.359 --> 01:55:01.934 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>给凯瑟琳写信</c>\n\n1656\n01:55:02.736 --> 01:55:04.645 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>给凯瑟琳克劳森的信</c>\n\n1657\n01:55:12.079 --> 01:55:13.362 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>“亲爱的凯瑟琳</c>\n\n1658\n01:55:13.747 --> 01:55:15.154 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我一直坐在这里</c>\n\n1659\n01:55:15.238 --> 01:55:17.824 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>思考那些我对不起你的事</c>\n\n1660\n01:55:20.462 --> 01:55:22.923 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>那些我们带给彼此的伤害</c>\n\n1661\n01:55:24.258 --> 01:55:25.707 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我对你的责备</c>\n\n1662\n01:55:28.919 --> 01:55:33.090 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>所有那些我对你的过分要求</c>\n\n1663\n01:55:36.937 --> 01:55:38.178 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>对不起</c>\n\n1664\n01:55:46.321 --> 01:55:48.021 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我会永远爱你\n因为我们见证了彼此的成长</c>\n\n1665\n01:55:49.157 --> 01:55:50.649 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>你成就了今日的我</c>\n\n1666\n01:55:55.831 --> 01:55:57.531 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我希望你知道</c>\n\n1667\n01:55:58.792 --> 01:56:01.243 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你在我的心中永远会有一席之地</c>\n\n1668\n01:56:03.714 --> 01:56:05.205 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>我也为此感恩</c>\n\n1669\n01:56:09.970 --> 01:56:14.006 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>无论你成为怎样的人\n无论你身在何方</c>\n\n1670\n01:56:15.517 --> 01:56:16.967 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>我都会将爱送给你</c>\n\n1671\n01:56:20.022 --> 01:56:21.430 align:middle line:85%,start position:50%,middle\n<c.styledotitalic>你是我永恒的好友</c>\n\n1672\n01:56:24.693 --> 01:56:25.809 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>爱你的 西奥多”</c>\n\n1673\n01:56:31.909 --> 01:56:32.858 align:middle line:85%,start position:50%,middle\n<c.styledotdefault>发送</c>\n";
